	# --- §8.4 EMG-001: Emergency SOS ---------------------------------------------------------
	('EMG-001', 'Features', 'Large, hard-to-mistap SOS button', 'deferred', None, 'a button is the client surface; the call it makes is `/emergency/sos`'),
	('EMG-001', 'Features', 'Sends location and a preset message to up to three emergency contacts', 'carried', 'afya.emergency.views:SOSEvent', '`contacts` is `EmergencyContact` capped at three by `max_length`, and `_sos_message` is the preset every leg carries — location, a maps link and the symptoms, composed GSM7-only so §5.3\'s zero-rating and `segment_sms` both hold. `SOSDispatch.contacts_notified` and `contacts_unreachable` split the fan-out by whether a message actually reached, because "3 contacts" for two deliveries is the failure this split exists to prevent'),
	('EMG-001', 'Features', 'Sends to the nearest ambulance dispatch where integrated', 'carried', 'afya.emergency.service:FacilityAmbulancePort', 'the ambulance leg reads §FND-001\'s own registry — `Facility.ambulances` is §FND-002\'s field, and a second list of bases would be a second answer to "where is the nearest one". "Where integrated" is the port existing at all: a deployment with no facility registry passes none and the dispatch reports the leg absent rather than inventing a base'),
	('EMG-001', 'Features', '**Works over SMS when data is unavailable**', 'carried', 'afya.emergency.service:EmergencyService._text_contacts', 'the contacts leg is SMS, sent through §5.3\'s channel service so the zero-rating claim is resolved where every other message\'s is. The client says which way its alert travelled (`SOSEvent.channel`), and the fan-out reaches the contacts the same way either way: a client with no data cannot POST at all, so the case the section bolds is the one where the alert was relayed in and the people who need telling are not on the app. `SOSDispatch.sms_sent` is how many messages went, so "told your contacts" is a count rather than a claim'),
	('EMG-001', 'Features', 'Countdown with cancel option (prevents accidental activation)', 'carried', 'afya.emergency.service:EmergencyService.arm', '`arm` returns the deadline and `cancel` refuses past it or after the alert has gone out — a late cancel reported as cancelled would leave a person believing nobody was told. The device owns the timer, because §ACC-004 wants no background polling and the section\'s Offline note wants the alert to work with no data; what the server owns is the window, the instant it closes, and that a cancelled alert never fires. `DEFAULT_COUNTDOWN_S` is a parameter because the section prints no figure'),
	('EMG-001', 'Features', 'Optional medical profile attachment (blood group, allergies, conditions, medications)', 'carried', 'afya.emergency.views:MedicalProfile', 'all four the section names, on the event and on the dispatch, and absent from the receipt when none was attached rather than an empty object that reads as "attached and blank". Flat on `SOSEvent` rather than nested because the catalogue renders one control per field and a generic form cannot build an object'),
	('EMG-001', 'Features', 'Optional auto-dial of emergency services', 'deferred', None, 'the device dials; `actions` names call-719 for the client to perform'),
	# --- §8.4 EMG-002: Fall Detection and Auto-Alert -----------------------------------------
	('EMG-002', 'Behaviour', 'Continuous low-power monitoring of tri-axis accelerometer and gyroscope', 'deferred', None, "continuous tri-axis sampling is the device's; `IMUSample` is the window a client submits, and §EMG-002 sits in the coverage gate's `ON_DEVICE` set — the server never holds a sensor stream"),
	('EMG-002', 'Behaviour', 'On-device classifier distinguishes falls from routine motion', 'carried', 'afya.emergency.service:EmergencyService.fall', None),
	('EMG-002', 'Behaviour', 'On detection: 30-second prompt ("Are you OK?")', 'deferred', None, 'the 30-second prompt is a client notification surface — `FallResult.auto_alert` is the decision the device renders, and no server model carries a prompt or a countdown'),
	('EMG-002', 'Behaviour', 'No response → automatic alert to emergency contacts and, if enabled, 719, with location', 'carried', 'afya.emergency.views:SOSEvent', "the fan-out is one mechanism for both sections: `SOSEvent.contacts` is the same named list §EMG-001's three-contacts bullet reads, `_text_contacts` reaches them by SMS and `Inline719Port` is the hotline leg — so a fall that no one answers arms the same alert a tap does, carrying the same lat/lon. The 30-second prompt above it stays the device's; this is the leg after it"),
	# --- §8.4 EMG-003: Offline Emergency Card ------------------------------------------------
	('EMG-003', 'Contents', 'Blood group', 'carried', 'afya.emergency.views:EmergencyCard', None),
	('EMG-003', 'Contents', 'allergies', 'carried', 'afya.emergency.views:EmergencyCard', None),
	('EMG-003', 'Contents', 'chronic conditions', 'carried', 'afya.emergency.views:EmergencyCard', 'the `conditions` field'),
	('EMG-003', 'Contents', 'current medications', 'carried', 'afya.emergency.views:EmergencyCard', 'the `medications` list, rendered into the QR payload by `card_qr`'),
	('EMG-003', 'Contents', 'emergency contacts', 'carried', 'afya.emergency.views:EmergencyContact', "a list of `EmergencyContact` rows carrying a name, a number and an optional relationship — the plural the section writes, and each row says *who* to ring rather than only what to dial, which is what a clinician reading an unconscious patient's card needs"),
	('EMG-003', 'Contents', 'organ donor status', 'carried', 'afya.emergency.views:EmergencyCard', '`organ_donor: bool | None` and rendered `yes`/`no`/`unknown` — tri-state because a defaulted `False` answers "never asked" as "declined", the one reading error on this card with a clinical consequence'),
	('EMG-003', 'Contents', 'SHA number', 'carried', 'afya.emergency.views:EmergencyCard', '`sha_number` on the payload, and no method here stores a card — the hash-only rule (`insurance.views:sha_of_member_no`) is about persistence, and §EMG-003 asks for the number a hospital can read off the card. The two are compatible because nothing writes one down'),
	('EMG-003', 'Access', 'Available from the lock screen without unlocking the phone (opt-in). Critical for unconscious patients', 'carried', 'afya.emergency.views:EmergencyCard', 'the first clause is `lock_screen_opt_in`, defaulted False, because the opt-in *is* the clause and the default is the one that shows a stranger nothing; the second is `EmergencyService.card_qr`, which renders all seven Contents into a QR payload — the form that works for a patient who cannot unlock a phone to show it'),
	# --- §8.5 INF-001: County Risk Dashboard -------------------------------------------------
	('INF-001', 'Displays', 'Current outbreak status by county (Ebola and other notifiable diseases)', 'carried', 'afya.info.views:CountyRisk', "`CountyRisk` carries `county`, `risk_level` (low/moderate/high) and `active_signals`, served per county by `InfoService.dashboard`; the disease dimension is `CountySignal.disease`, so the 'Ebola and other notifiable diseases' half is carried by the signal rather than by a disease list on the row."),
	('INF-001', 'Displays', 'Case counts (confirmed, suspected) with trend', 'carried', 'afya.info.views:CaseCounts', '`CaseCounts` carries `confirmed` and `suspected` as separate fields and the trend as a `@computed_field` derived from the two periods — `new` where no earlier period exists, so a first report is not called steady. The previous period is carried forward from the row already on file (`InfoService.record_case_counts`) rather than restated by the caller, and one row per disease because the section\'s first Display is "Ebola and other notifiable diseases".'),
	('INF-001', 'Displays', 'Affected sub-counties and locations', 'carried', 'afya.info.views:SubCountyStatus', '`SubCountyStatus` carries the sub-county, its disease, its confirmed and suspected counts and the named `locations` inside it; `model_post_init` refuses an "affected" area with no case and no location, so a place with nothing to report cannot reach the screen. Recorded through `POST /info/dashboard/{county}/sub-counties` and served worst-first by `InfoService.sub_counties`.'),
	('INF-001', 'Displays', 'Active alerts and advisories', 'carried', 'afya.alerts.views:AlertKind', '`AlertKind` enumerates the advisories (an `outbreak_*` per disease plus flood, water_quality, school_closure, public_health_notice) and `AlertsService.by_county` serves the ones for a county.'),
	('INF-001', 'Displays', 'Service status (schools, borders, markets — where available)', 'carried', 'afya.info.service:InfoService.county_dashboard', "§INF-007 is the producer — `AlertsService.publish_status` writes a `ServiceStatus` per school, market, border post, water supply, road or transport route — and this Display is the same fact on the dashboard, read from that service rather than restated, so the two surfaces cannot disagree. The section's 'where available' is answered by the feed being empty rather than by a placeholder row. `RankedQuestion` rank 10's question now has an answer behind it."),
	('INF-001', 'Displays', 'Last updated timestamp', 'carried', 'afya.info.views:CountyRisk', '`CountyRisk.updated_at_ms` defaults to `UNDATED_MS`, so a county with no signal is still served a low-risk row that carries a stamp.'),
	('INF-001', 'Displays', 'Data source attribution', 'carried', 'afya.info.views:CountyRisk', '`CountyRisk.source` is the attribution field, defaulting to an empty string.'),
	# --- §8.5 INF-002: "What Should I Do?" Decision Tree -------------------------------------
	('INF-002', 'Entry questions', 'I have a fever', 'carried', 'afya.info.service:ENTRY_ANSWERS', '`ENTRY_ANSWERS` is the section\'s six in its own order, served at `/info/entry-answers`. The first opens the fever walk with `kind=\'tree\'`; `tests/ci/test_decision_tree.py` reads the six off `docs/spec.md` and asserts the served list matches, so the menu cannot drift from the section.'),
	('INF-002', 'Entry questions', 'Someone in my house is sick', 'carried', 'afya.info.service:InfoService.TREE', 'a second root, `TREE[\'household\']`, reached by `/info/decision-tree?entry=household`. It is a root rather than a branch because routing it through the fever tree makes the caller answer "no" to a question about their own temperature and be told no action is needed, while the person in their house is the one who is unwell. Its two leaves are disjoint from the fever walk\'s four, asserted in the test.'),
	('INF-002', 'Entry questions', "I'm worried about travel", 'carried', 'afya.info.service:ENTRY_ANSWERS', 'the third entry, `kind=\'screen\'`, opening `/location/travel-advisory` — `LocationService.advisory`\'s own route. `asks_for` names the two arguments the route requires, so a client prompts for them rather than opening a door that returns 422; the test reads the route signature and asserts the two agree.'),
	('INF-002', 'Entry questions', 'I want to protect my family', 'carried', 'afya.info.service:ENTRY_ANSWERS', 'the fourth entry, opening `/info/library` with `tag=ebola-library` — the handwashing, prevention and safe-burial items. `info_library` gained the `tag` filter for this and the next entry: without it an entry question opens the whole corpus and leaves the reader to find their own section.'),
	('INF-002', 'Entry questions', 'I heard something — is it true?', 'carried', 'afya.info.service:ENTRY_ANSWERS', 'the fifth entry, opening `/info/library?tag=mythbusting` — §INF-004\'s rumour corpus, which carries the claim and its correction as one item in the section\'s own Rumour/Fact/Source form. It does not open `flag_misinfo`: submitting a claim for verification is §INF-004\'s third Feature and is a different act from reading whether one is true.'),
	('INF-002', 'Entry questions', 'I need to go to hospital', 'carried', 'afya.info.service:ENTRY_ANSWERS', 'the sixth entry, opening `/places/nearest` — the facility search, with `asks_for=[\'lat\', \'lon\']` because a search with no position has no answer. The tree\'s leaves carry the same destination as an `InfoLink` of `kind=\'find_facility\'`.'),
	('INF-002', 'Output', 'Specific', 'carried', 'afya.info.views:DecisionStep', '`DecisionStep` is the output shape: `done` says whether the walk is asking or answering, so a client cannot render a question as a recommendation; `question` is None exactly at a leaf and `recommendation` is None exactly at an interior node. "Specific" is what the two extra leaves are — the household walk answers the household question rather than the caller\'s own.'),
	('INF-002', 'Output', 'actionable guidance with facility and hotline links', 'carried', 'afya.info.views:InfoLink', '`LEAF_LINKS` gives every leaf the two destinations the section names as `InfoLink` rows the client dispatches — `tel:719` and the facility search — asserted at import to cover exactly the tree\'s leaves, in both directions, so a leaf with nowhere to go and a button under a question both fail. `leaf_ok` is deliberately empty: "No action needed" is the answer, and a facility button under it sends someone who needs nothing to a clinic.'),
	# --- §8.5 INF-003: Ebola Information Library ---------------------------------------------
	('INF-003', 'Topics', 'What Ebola is and how it spreads', 'carried', 'afya.info.content_seed:seed_rows', '`EBOLA_TOPICS` names the topic and the `what-is-ebola` item states the transmission route; `coverage()` reports it covered against the `ebola-library`-tagged corpus.'),
	('INF-003', 'Topics', 'Symptoms and when they appear', 'carried', 'afya.info.content_seed:seed_rows', '`EBOLA_TOPICS` names the topic and the `symptoms` item lists the signs and the 2–21 day incubation; `coverage()` reports it covered against the `ebola-library`-tagged corpus.'),
	('INF-003', 'Topics', 'How to protect yourself and your family', 'carried', 'afya.info.content_seed:seed_rows', '`EBOLA_TOPICS` names the topic and the `protect-your-family` item is the household-protection guidance; `coverage()` reports it covered against the `ebola-library`-tagged corpus.'),
	('INF-003', 'Topics', "What to do if you think you've been exposed", 'carried', 'afya.info.content_seed:seed_rows', '`EBOLA_TOPICS` names the topic and the `exposed` item is the 21-day monitoring and 719 guidance; `coverage()` reports it covered against the `ebola-library`-tagged corpus.'),
	('INF-003', 'Topics', 'Testing and treatment', 'carried', 'afya.info.content_seed:seed_rows', '`EBOLA_TOPICS` names the topic and the `testing-and-treatment` item covers the test and the supportive-care case; `coverage()` reports it covered against the `ebola-library`-tagged corpus.'),
	('INF-003', 'Topics', 'Safe and dignified burial (see INF-010)', 'carried', 'afya.info.content_seed:seed_rows', "`EBOLA_TOPICS` names the topic and the `safe-burial` item is §INF-010's guidance and `EBOLA_TOPICS` names it here; `coverage()` reports it covered against the `ebola-library`-tagged corpus."),
	('INF-003', 'Topics', 'Stigma and how to fight it', 'carried', 'afya.info.content_seed:seed_rows', '`EBOLA_TOPICS` names the topic and the `stigma` item is the anti-stigma guidance; `coverage()` reports it covered against the `ebola-library`-tagged corpus.'),
	('INF-003', 'Topics', 'What happens at an isolation facility', 'carried', 'afya.info.content_seed:seed_rows', '`EBOLA_TOPICS` names the topic and the `isolation-facility` item is the treatment-unit walkthrough; `coverage()` reports it covered against the `ebola-library`-tagged corpus.'),
	('INF-003', 'Topics', 'Recovery and survivors', 'carried', 'afya.info.content_seed:seed_rows', '`EBOLA_TOPICS` names the topic and the `recovery` item covers survivor immunity and the long-term effects; `coverage()` reports it covered against the `ebola-library`-tagged corpus.'),
	('INF-003', 'Format', 'Short articles (under 200 words)', 'carried', 'afya.info.content_seed:seed_rows', "Every `afya.info.content_seed:seed_rows` row is an article, and `over_length()` checks each against §INF-003's own `ARTICLE_MAX_WORDS = 200` and reports the slugs that exceed it."),
	('INF-003', 'Format', 'illustrations', 'carried', 'afya.info.content_seed:seed_rows', '`ContentItem.format` is `ContentFormat.illustration` and the model refuses one without a `media_ref`, so an illustration is a rendition with a file behind it rather than a claim; `format_coverage()` reports the format delivered when the corpus carries one.'),
	('INF-003', 'Format', 'audio versions', 'carried', 'afya.info.content_seed:seed_rows', '`ContentFormat.audio` with its `media_ref`; the seed carries the audio renditions and `format_coverage()` reports the format delivered.'),
	('INF-003', 'Format', 'video versions', 'carried', 'afya.info.content_seed:seed_rows', '`ContentFormat.video` with its `media_ref`; the seed carries the video renditions and `format_coverage()` reports the format delivered.'),
	# --- §8.5 INF-004: Myth-Busting Library --------------------------------------------------
	('INF-004', 'Format', '"Rumour: [claim]. Fact: [correction]. Source: [authority]."', 'carried', 'afya.info.content_seed:myth_rows', '`afya.info.myths.MYTHS` holds the three parts as fields and `myth_rows` writes each row with `claim` and `source` beside `body` — `ContentItem` asserts the claim and the authority travel together and that only a `mythbusting` item carries them, so a rumour held as one `body` string can no longer be constructed. `ContentItem.share_card` renders the section\'s own three-line Format from those fields rather than by parsing prose.'),
	('INF-004', 'Features', 'Search', 'carried', 'afya.info.service:InfoService.search', '`InfoService.search(query, lang, tag)` matches every term over the lowercased claim, title and body of the served corpus and is surfaced as `GET /info/library?q=`. The claim is the half that needed the corpus to carry one: "salt water" is a rumour, and while the rumour lived as prose inside `body` it was findable by accident rather than on purpose. `/info/myths?q=` reads the same implementation, so the two cannot disagree about what matches.'),
	('INF-004', 'Features', 'Browse by category', 'carried', 'afya.info.service:InfoService.facets', '`InfoService.facets(lang)` returns `{tag, count, label}` per harmony tag and is served as `GET /info/library/categories`. Counts are read through `library()`, not off the store, so a facet is offered only when something is behind it — a browse screen that opens onto an empty list because the facet counted a draft is the failure the count exists to prevent.'),
	('INF-004', 'Features', '"Ask about a rumour" — submit a claim for verification', 'carried', 'afya.community.service:CommunityService.answer_claim', '`answer_claim(claim, lang)` classifies the claim against `MYTH_KEYWORDS`, returns the drafted correction with its authority, and is served as `POST /info/myths/ask`. Deliberately not `flag_misinfo`, which takes a rumour someone *else* spread and returns PHEOC a cluster: a person asking whether something is true is not reporting anything, and answering them with a surveillance row is answering a question they did not ask. An unmatched claim is answered "under verification" with `recognised=false` rather than attached to the nearest rumour.'),
	('INF-004', 'Features', 'Shareable as a card', 'carried', 'afya.info.views:ContentItem.share_card', '`share_card` and `share_url` are `@computed_field`s rendered server-side for §3.3 principle 10\'s reason: §5.4 puts this answer on WhatsApp, USSD and SMS, and only one of those can compose a forwardable message. The card is §INF-004\'s own three-line Format for a myth and the title plus body for anything else, and `share_url` is the same `wa.me` deep link `HotlineActions.share_url` uses.'),
	# --- §8.5 INF-005: Travel Advisory -------------------------------------------------------
	('INF-005', 'Features', 'Country and county advisories', 'carried', 'afya.location.advisories:COUNTRIES', 'both halves are tables now. The country half is `COUNTRIES` — WHO\'s own risk bands read from the v4 rapid risk assessment, with the three named countries at `high`, the DRC at `very_high`, and Kenya at `not_assessed` because WHO had not finished assessing it when the notice was published. The county half reads §INF-001\'s `CountyRisk` through `InfoService.dashboard` rather than keeping a second table, so a county office\'s published risk reaches the traveller screen without being re-entered. `LocationService.place_advisory` tries the county table first and the country table second, and answers `kind=unknown` — never `low` — for a city or a name no table matches.'),
	('INF-005', 'Features', 'Border point status and wait times', 'carried', 'afya.location.views:BorderPost', 'queue_minutes and screening_required, read via border_status'),
	('INF-005', 'Features', 'Screening requirements', 'carried', 'afya.location.views:BorderPost', 'screening_required'),
	('INF-005', 'Features', 'What to do if you feel unwell after travel', 'carried', 'afya.location.advisories:POST_TRAVEL_STEPS', 'five steps, not the one fixed sentence the row named: 21 days of monitoring and "seek medical care immediately" from CDC, the symptom set from WHO\'s fact sheet, and the 719 call and the arrival declaration as this deployment\'s own operating rule. Each step carries `source` through `STEP_SOURCES`, so the two the sources state and the two they do not are distinguishable in the payload rather than presented as one authority\'s. `TravelAdvisoryReport.traveller_risk_note` carries the source\'s own correction — "the viruses that cause Ebola disease pose little risk to travelers or the general public" — because a reader who sees only the bands would conclude the opposite.'),
	('INF-005', 'Features', '21-day self-monitoring enrolment for travellers (links to MON-009)', 'carried', 'afya.location.service:LocationService.self_declare', 'the enrolment now reaches `MonitoringService.enrol`, which is what the row said it did not: the link was a message string and the diary stayed empty. `LocationService` is handed the monitoring service at wiring time and `self_declare` enrols the traveller, so `/monitoring/contact/{ref}/diary` has a window to file against; `TravellerEnrolment.diary_linked` reports whether it did, and a deployment with no monitoring service wired says `False` rather than promising a schedule nothing will ask about.'),
	# --- §8.5 INF-006: Hotline and Contact Directory -----------------------------------------
	('INF-006', 'Contents', '719 hotline', 'carried', 'afya.info.service:HOTLINES', 'the "Ministry of Health Hotline" row, number 719, `kind=emergency_hotline`'),
	('INF-006', 'Contents', 'county health office', 'carried', 'afya.info.service:InfoService._county_office_rows', 'a number per county, registered by `POST /info/county-office` (infrastructure-scoped) and composed into the directory only when the caller names a county the deployment has a number for — the same shape as "nearest facility", and reported in `absent` otherwise rather than listed with nothing to dial'),
	('INF-006', 'Contents', 'nearest facility', 'carried', 'afya.info.service:InfoService._nearest_facility_rows', "composed from the caller's position over `PlacesService.nearest` and `Place.phone`, so the row exists only when `lat`/`lon` are given — a nearest facility is an answer about where the caller is, and without a position the kind is reported `absent` rather than guessed"),
	('INF-006', 'Contents', 'ambulance', 'carried', 'afya.info.service:COUNSELLING_KINDS', 'the tree\'s own "1199 (ambulance) / 719 (MoH)" row, folded into the directory under `kind=ambulance`; `_dialable` cuts it to 1199 because stripping both numbers concatenates them into `1199719`, which dials nothing'),
	('INF-006', 'Contents', 'CHW', 'carried', 'afya.chw.service:ChwService.serving', '`ChwProfile.phone` is new — the profile carried a name, a county and a community and no way to reach the person, so the Content was unanswerable even for a deployment that had provisioned every worker. `serving(county)` picks the lowest `chw_ref` among the county\'s workers, which is stable across restarts; a worker with no number on file yields no row and the kind is reported `absent`'),
	('INF-006', 'Contents', 'mental health helpline', 'carried', 'afya.info.service:_directory_rows', "Befrienders Kenya's number, folded in from `mental.COUNSELLING_LINES` — the table the directory route never read — so the two modules cannot drift; `mental` keeps the row"),
	('INF-006', 'Contents', 'GBV helpline', 'carried', 'afya.info.service:HOTLINES', '1195, Kenya\'s National Gender-Based Violence Toll-Free Helpline, and GVRC\'s 0800720565 — both archived in `sources/helpline-directory/` with what each source states (UN Women for 1195: 24/7, multilingual, SMS route because a survivor may not be able to speak). `verified=False`: the operators\' own statements, not confirmed against MoH/PHEOC'),
	('INF-006', 'Contents', 'child helpline', 'carried', 'afya.info.service:HOTLINES', '116, the National Child Helpline, owned by the Government through the Department of Children Services and managed by Childline Kenya; archived in `sources/helpline-directory/childline-kenya-116.html`'),
	('INF-006', 'Features', 'One-tap call', 'carried', 'afya.info.views:HotlineActions', '`tel_uri` rendered by `InfoService.hotline_actions` off `_dialable`, so a row naming two numbers or written `+254-20-4226849` still dials'),
	('INF-006', 'Features', 'one-tap SMS', 'carried', 'afya.info.views:HotlineActions', '`sms_uri`, the same handoff as `tel_uri` — "one-tap" is the client opening the messaging composer with the number prefilled, which is what a `sms:` URI does. §EMG-001\'s "works over SMS when data is unavailable" is a different claim and still has no path'),
	('INF-006', 'Features', 'save to contacts', 'carried', 'afya.info.views:HotlineActions', 'a vCard 3.0 body rendered server-side — there is no cross-platform scheme for "save a contact" the way there is for dialling, so the client hands the text to the contacts app'),
	('INF-006', 'Features', 'share', 'carried', 'afya.info.views:HotlineActions', '`share_url`, a `wa.me` deep link carrying the name, number and hours — §3.3 principle 10 requires every output be shareable as a WhatsApp card, and a card needs a link to carry'),
	# --- §8.6 LOC-001: Geofenced Risk Alerts -------------------------------------------------
	('LOC-001', 'Alert content', '"You have entered an area where a case was reported. Avoid [specific location]. Monitor for symptoms for 21 days. Call 719 if you feel unwell."', 'carried', 'afya.strings:zone_transition', "the section's sentence is a string table entry, not a line written at the route, and `[specific location]` resolves through `afya.strings:zone_place`: the zone's own `place_label` when the county health authority set one, the county when it did not, and the section's words said plainly when the registry knows neither. The row was `missing` because the route emitted a near-verbatim line inline and replaced the section's bracket with 'the named location' — the one action the sentence asks for, asked of a place the sentence declined to name. The entry and exit halves are separate strings, because an exit is not an all-clear: the 21-day watch that started on entry is still running."),
	# --- §9.1 MON-001: Child Immunisation Tracker --------------------------------------------
	('MON-001', 'Features', 'Add children with date of birth', 'carried', 'afya.monitoring.service:MonitoringService.register_child', None),
	('MON-001', 'Features', 'Automatic schedule generation (BCG, OPV, Pentavalent, PCV, Rotavirus, Measles-Rubella, Yellow Fever where relevant, HPV for girls)', 'carried', 'afya.monitoring.views:EPI_DUE_WEEKS', 'all nine named vaccines are rows; the section spells two of them differently ("Pentavalent" is `DPT-HepB-Hib`, "Rotavirus" is `RV`)'),
	('MON-001', 'Features', 'Reminders 3 days and 1 day before due date', 'carried', 'afya.monitoring.views:REMINDER_LEAD_DAYS', '`schedule` fills `remind_days_before` from it'),
	('MON-001', 'Features', 'Record doses given (with photo of card)', 'carried', 'afya.records.views:ImmunisationRecord', '`card_photo_sha256` carries the photo of the card as a 64-hex digest and is optional, so a dose logged without one is still a dose; `record_dose` writes through to `RecordsService.record_immunisation`, so the dose the tracker takes is the dose the wallet holds.'),
	('MON-001', 'Features', 'Catch-up schedule for defaulters', 'carried', 'afya.monitoring.service:MonitoringService.catch_up', None),
	('MON-001', 'Features', 'Missed-dose alerts', 'carried', 'afya.monitoring.service:MonitoringService.missed_dose_alerts', 'an alert per dose, split into `overdue` (with `days_overdue`) and `due_soon` (from `REMINDER_LEAD_DAYS`), served as data for the device to schedule — §ACC-004 wants no background polling. `immunisation_reminders` now has a producer: `publish_campaign` files under the `immunisation` feed category, which `FEED_PREFERENCE` maps to that toggle.'),
	('MON-001', 'Features', 'Facility finder integration for vaccination points', 'carried', 'afya.places.views:PlacesService.nearest', 'the kind exists and `/places/vaccination-points` serves it; the immunisation schedule does not call it, so the client has to join the two itself'),
	('MON-001', 'Features', 'Campaign notifications (polio, measles)', 'carried', 'afya.monitoring.service:MonitoringService.publish_campaign', '`CampaignNotice` carries the disease slug, the counties, the age band and the window; `publish_campaign` files one verified `FeedItem` per county under the `immunisation` category, and `campaigns(county, on_iso)` returns only those running that day. Polio is expressible as a campaign target precisely because it is not a §3.3 principle 12 outbreak disease, so it is never an `AlertKind`.'),
	('MON-001', 'Features', 'Shareable immunisation record', 'carried', 'afya.records.service:RecordsService.grant_share', 'the wallet\'s own `ShareGrant`, over the `immunisation` document kind, with `share_view` enforcing the expiry — a second share mechanism with its own expiry rule would be the second rule that drifts. `vaccination_certificate` renders the same dose log.'),
	# --- §9.1 MON-002: Pregnancy and Antenatal Care Tracker ----------------------------------
	('MON-002', 'Features', 'Estimated due date calculator', 'carried', 'afya.maternal.service:MaternalService.estimated_due_date', 'Naegele\'s rule: `estimated_due_date(lmp_iso)` adds `GESTATION_DAYS` = 280 to the first day of the last period, and `/maternal/due-date` serves it without a subject or a record. `lmp_iso` is now on `Pregnancy` so the calculator and the registration agree, and `gestation_week` reads the same number back off either the LMP or a clinic-card EDD.'),
	('MON-002', 'Features', 'WHO/Kenya ANC visit schedule (8 contacts)', 'carried', 'afya.maternal.views:ANC_CONTACTS_WEEKS', '8 contacts at 12/20/26/30/34/36/38/40 weeks'),
	('MON-002', 'Features', 'Visit reminders', 'carried', 'afya.maternal.service:MaternalService.visits', '`visits()` returns each of the eight contacts with the date it falls on — derived from the LMP, or from the EDD when there is none — and the 3-day/1-day leads, which is what a reminder needs and a contact number is not. A contact already recorded carries no lead. `/maternal/{ref}/visits` serves it.'),
	('MON-002', 'Features', 'Danger sign education and one-tap escalation', 'carried', 'afya.maternal.service:MaternalService.assess_danger', 'the assessment now carries `education` — one row per sign reported, from `DANGER_SIGN_EDUCATION`, keyed to every member of `DANGER_SIGNS` by an import-time assertion — and `action`, a `CareAction` the client dispatches. The order is the classification\'s: the three signs that cannot wait lead with `tel:719`, the rest with the maternity finder.'),
	('MON-002', 'Features', 'Birth plan builder (facility, transport, birth companion, blood donor, funds)', 'carried', 'afya.maternal.views:BirthPlan', 'the five fields the section names, each optional so the plan can be built over several conversations, with `gaps()` returning the ones still unanswered in the section\'s order. `/maternal/birth-plan` serves the plan and its gaps together, so a screen cannot render an incomplete plan as a finished one.'),
	('MON-002', 'Features', 'Trimester-specific guidance', 'carried', 'afya.maternal.views:TRIMESTER_GUIDANCE', 'three rows keyed by trimester, each an advice line and four points, with the trimester derived from the gestational week. Asserted at import to cover all three, so a pregnancy cannot reach a trimester with nothing behind it.'),
	('MON-002', 'Features', 'Postnatal visit reminders', 'carried', 'afya.maternal.service:MaternalService.postnatal_visits', 'the four WHO postnatal contacts (day 1, day 3, day 7–14, week 6) counted from a recorded birth date, which `record_birth` is the new carrier for. Before the birth the list is empty rather than provisional: four dates derived from a delivery that has not happened are four wrong dates.'),
	('MON-002', 'Features', 'Newborn danger signs', 'carried', 'afya.maternal.views:NEWBORN_DANGER_SIGNS', 'eight signs of the newborn — not feeding, convulsions, fast breathing, hot, cold, jaundice, cord infection, floppy — a different list from the mother\'s, served at `/maternal/newborn-signs`. The one sign the two share is a convulsion, which is a convulsion in either.'),
	('MON-002', 'Features', 'Facility finder for maternity services', 'carried', 'afya.maternal.service:MATERNITY_FINDER_HREF', 'the finder is §FND-001\'s own, with `ServiceOffered.maternal` pinned the way `/places/pharmacies` pins its kind — `FacilityKind` still has no maternity member and does not need one, because the service is the dimension the section filters on. `/maternal/facilities` serves it with `level` and `accepts_sha` open, and `unanswered` travelling as it does on the general finder.'),
	('MON-002', 'Features', 'Referral to PMTCT where relevant', 'carried', 'afya.maternal.service:MaternalService.pmtct_referral', 'a referral that takes the boolean the caller derived at the point of care and never the result itself — the status does not reach this module, which has no PIN on it (§9.1\'s rule for the same fact at §MON-003). `programme` is named only when the referral is relevant.'),
	# --- §9.1 MON-003: Chronic Disease Log ---------------------------------------------------
	('MON-003', 'Conditions supported', 'Hypertension', 'carried', 'afya.chronic.views:BPReading', '`BPReading.stage` is the hypertension reading — `systolic >= 140 or diastolic >= 90` — stored by `ChronicService.bp`. `ConditionProfile.conditions` is a free-text list, so "hypertension" is a string a person types and the thresholds are the only place the condition is a model.'),
	('MON-003', 'Conditions supported', 'Diabetes', 'carried', 'afya.chronic.views:GlucoseReading', '`GlucoseReading.level` is the diabetes reading, with fasting and post-prandial cut-offs in one model, stored by `ChronicService.glucose`.'),
	('MON-003', 'Conditions supported', 'Asthma', 'carried', 'afya.monitoring.service:MonitoringService.log_peak_flow', 'peak flow is the asthma reading: `log_peak_flow` scores `litres_per_min` against a personal best and returns a green/yellow/red zone with inhaler advice.'),
	('MON-003', 'Conditions supported', 'Epilepsy', 'carried', 'afya.chronic.conditions:assess_seizure', 'ILAE 2015\'s two time points — `SEIZURE_EMERGENCY_MINUTES` 5 and `STATUS_EPILEPTICUS_MINUTES` 30 — with a cluster escalating at any duration and any seizure in pregnancy needing same-day review. `SeizureEvent` is the reading and `PROPHYLAXIS`/`DANGER_SIGNS[\'epilepsy\']` are the guidance; `ChronicService.seizure` records it.'),
	('MON-003', 'Conditions supported', 'HIV (with strong privacy protections)', 'carried', 'afya.monitoring.views:ConditionProfile', '`hiv_pin_set` is the separate PIN §9.1 requires and `set_conditions` refuses an HIV profile without it; `shareable_report` withholds HIV unless separately consented. HIV is a string in `conditions`, so the protections are gates around a free-text list rather than a typed field.'),
	('MON-003', 'Conditions supported', 'Sickle cell disease', 'carried', 'afya.chronic.conditions:assess_sickle_crisis', '`SickleCrisis` is the painful crisis; a fever at `SICKLE_FEVER_C` and the six signs in `SICKLE_CRISIS_SIGNS` (acute chest syndrome, splenic sequestration, stroke, a falling haemoglobin) each escalate on their own. `PROPHYLAXIS[\'sickle_cell\']` carries the daily penicillin and vaccination guidance and states that the archived source gives no milligram dose.'),
	('MON-003', 'Conditions supported', 'Chronic kidney disease', 'carried', 'afya.chronic.conditions:egfr_ckdepi_2021', 'CKD-EPI 2021 from creatinine, age and sex; `kidney_stage` is KDIGO\'s G1-G5 (G3 split at 45) and `albuminuria_stage` its A1-A3. `assess_kidney` reports the stage and separately whether the history sustains it, because `CKD_SUSTAINED_DAYS` is 90 and one low eGFR is an acute finding.'),
	('MON-003', 'Features', 'Log readings (BP, blood sugar, peak flow, weight)', 'carried', 'afya.chronic.service:ChronicService.bp', '`glucose`, `log_peak_flow` and `log_weight` too. The peak-flow and weight readings now store a dated series as well as returning a verdict — `MonitoringService.peak_flow_series` and `weight_series` — which is what the trend chart reads.'),
	('MON-003', 'Features', 'Trend charts', 'carried', 'afya.chronic.trends:build_chart', 'one builder for all five metrics, served by `GET /chronic/{ref}/chart`. The direction is the first third against the last third — a fixed three-point window is identically zero at exactly three readings, which is the smallest series a chart accepts. The peak-flow and weight series are read from `MonitoringService` rather than copied, so there is one series and one chart.'),
	('MON-003', 'Features', 'Medication reminders', 'carried', 'afya.monitoring.views:MedSchedule', "`times_per_day` and `duration_days` are the schedule; the section lists this under MON-003 and the model is MON-004's, so the two sections share one carrier"),
	('MON-003', 'Features', 'Refill reminders', 'carried', 'afya.chronic.service:ChronicService.set_refill', '`refill_due` at seven days remaining'),
	('MON-003', 'Features', 'Appointment tracking', 'carried', 'afya.chronic.trends:appointment_status', '`next_review` computes the due date from `review_interval_days`, which is the condition\'s interval and, for kidney disease, the stage\'s — a stored date goes stale the moment the stage changes. `overdue` and `remind` are separate answers because "you missed this" and "this is in a week" are different sentences, and `APPOINTMENT_LEAD_DAYS` is 14.'),
	('MON-003', 'Features', 'Lifestyle guidance', 'carried', 'afya.chronic.trends:lifestyle', 'keyed on the condition rather than the age: `LIFESTYLE` carries a guidance list, an avoid list and a note for each of the seven conditions. `nutrition_guidance` bands by age, which is right for a well-child visit and wrong here — what a person with hypertension eats and what a person with sickle cell must avoid differ at the same age.'),
	('MON-003', 'Features', 'Shareable reports for clinicians', 'carried', 'afya.monitoring.service:MonitoringService.shareable_report', 'the report withholds HIV unless separately consented'),
	('MON-003', 'Features', 'Danger thresholds with escalation', 'carried', 'afya.chronic.views:BPReading.stage', '`stage`, `level` and `ALERT_LIMITS` set the thresholds; escalation is a `_log_warn`, which is a server log and not a message to anyone'),
	# --- §9.1 MON-004: Medication Reminders --------------------------------------------------
	('MON-004', 'Features', 'Add medication, dose, frequency, duration', 'carried', 'afya.monitoring.views:MedSchedule', 'drug, dose, times_per_day and duration_days'),
	('MON-004', 'Features', 'Multiple daily reminders', 'carried', 'afya.monitoring.views:reminder_times', '`REMINDER_CLOCK` gives each of the 1-6 frequencies its own instants and the service derives them from `times_per_day`, so a count is never served where a time is needed. A table rather than arithmetic: dividing 24 hours by six gives 04:00 as the first dose, and the route returns the times with the schedule id.'),
	('MON-004', 'Features', 'Mark as taken / skipped / snooze', 'carried', 'afya.monitoring.views:AdherenceAction', 'taken, skipped, snoozed'),
	('MON-004', 'Features', 'Adherence history', 'carried', 'afya.monitoring.service:MonitoringService.adherence', 'counts by action over the schedule; `record_adherence` keeps the events'),
	('MON-004', 'Features', 'Refill alerts when supply is running low', 'carried', 'afya.monitoring.views:MedSchedule', '`adherence` raises `refill_due` from it'),
	('MON-004', 'Features', 'Support for multiple family members', 'carried', 'afya.monitoring.views:MedSchedule', "keyed per member; the route binds the member to the caller's own wallet"),
	('MON-004', 'Features', 'Works with no data connection', 'carried', 'afya.monitoring.service:MonitoringService.record_adherence', 'a dose is recorded locally and queued through `SyncService.enqueue` under the `medication` dataset §16.3 already carries a rule for, so the strategy on replay is the spec\'s own; the queue is injected by the composition root, so a route cannot record a dose and lose it'),
	# --- §9.2 REC-001: Family Health Wallet (Basic) ------------------------------------------
	('REC-001', 'Contents', 'Immunisation cards (photo or digital)', 'carried', 'afya.records.views:ImmunisationRecord', 'the EPI schedule and the doses given are modelled; the card itself is not stored as an image'),
	('REC-001', 'Contents', 'ANC cards', 'carried', 'afya.maternal.views:ANCRecord', 'the eight ANC contacts are modelled against the visit schedule'),
	('REC-001', 'Contents', 'Lab results', 'carried', 'afya.records.views:LabResult', None),
	('REC-001', 'Contents', 'Prescriptions', 'carried', 'afya.records.views:Prescription', None),
	('REC-001', 'Contents', 'Discharge summaries', 'carried', 'afya.records.views:WalletDocument', 'the `discharge` kind of the wallet document envelope; a facility writes one and the person files it, which is how the other seven documents arrive too'),
	('REC-001', 'Contents', 'Referral letters', 'carried', 'afya.intermediaries.views:Referral', 'the referral is modelled for code attribution, and the `referral` kind of `WalletDocument` is where the letter itself is filed'),
	('REC-001', 'Contents', 'Insurance/SHA details', 'carried', 'afya.records.views:InsuranceCard', 'the SHA member number is stored as a hash, so the card cannot be reconstructed from it; the `insurance` kind carries the card as a document'),
	('REC-001', 'Contents', 'Clinic appointment cards', 'carried', 'afya.facilities.views:Booking', 'the booking is modelled and the `appointment` kind of `WalletDocument` is where the printed card is filed'),
	('REC-001', 'Features', 'Multiple profiles (up to 10)', 'carried', 'afya.records.service:MAX_WALLET_PROFILES', 'enforced at enrolment: `add_member` refuses the eleventh profile for a guardian'),
	('REC-001', 'Features', 'Photo capture and storage', 'carried', 'afya.records.views:WalletDocument', '`media_ref` plus `captured_iso` on the document envelope: the wallet stores the reference the camera upload returns and never the bytes, the same split `ContentItem.media_ref` uses for audio and video'),
	('REC-001', 'Features', 'Offline access', 'carried', 'afya.sync.service:SyncService.offline_state', "the write queue and its indicator, plus `WalletDocument` as a serialisable payload the client caches; §15.2 records that the client keeps the last good response in SharedPreferences, so the on-device half is the device's and the payload half is now here"),
	('REC-001', 'Features', 'Share via secure link or PDF export', 'carried', 'afya.records.service:RecordsService.grant_share', 'one grant mechanism with a mandatory `expires_iso`, and `RecordsService.export` rendering a real PDF through `afya.records.pdf` — the section\'s "or" is two operations over one document set, not two features'),
	('REC-001', 'Features', 'Optional encrypted cloud backup', 'carried', 'afya.records.service:RecordsService.backup', '`backup` refuses without the subject\'s `cloud_backup` consent and returns an envelope whose `cipher` and `user_held_key` state what it actually is: this deployment holds no key it does not also hold the data with, so it reports `none`/False rather than inheriting `retention.encryption_posture`\'s design claim'),
	('REC-001', 'Features', 'Search', 'carried', 'afya.records.service:RecordsService.search', 'a case-insensitive match across title, detail and kind over every document the caller may read, across the whole wallet rather than one member at a time'),
	# --- §9.3 MED-004: Drug Stock Crowdsourcing ----------------------------------------------
	('MED-004', 'Features', 'Search for a medicine', 'carried', 'afya.medicine.service:MedicineService.search_stock', 'across drugs, which `stock_for` cannot do: it is keyed on (drug, facility) and needs both, so it answers "is this drug at this place" and not "where is this drug" — the question the section\'s example actually asks'),
	('MED-004', 'Features', 'See recent reports ("available at [pharmacy], 2 hours ago")', 'carried', 'afya.medicine.views:StockAvailability', '`at_iso` on the report and `age_hours` on the availability, so the section\'s own sentence renders. Age is a duration rather than a timestamp because "clearly" means a client prints it without diffing against its own clock — wrong on a phone whose clock is wrong, impossible on one with none'),
	('MED-004', 'Features', 'Report availability yourself (one tap)', 'carried', 'afya.medicine.service:MedicineService.report_stock', None),
	('MED-004', 'Features', 'Flag stockouts', 'carried', 'afya.medicine.views:StockReport', 'in_stock=False is the flag'),
	('MED-004', 'Features', 'Essential medicines list prioritised (insulin, ARVs, TB drugs, oxytocin, malaria ACTs, ORS, zinc, contraceptives)', 'carried', 'afya.medicine.views:ESSENTIAL_MEDICINES', 'the section\'s eight, each with the aliases a crowd-sourced report arrives under — a person typing "ARVs" and one typing "dolutegravir" mean the same medicine. `search_stock` sorts essential first, which is what "prioritised" asks for'),
	('MED-004', 'Features', 'Alert when a previously out-of-stock medicine becomes available', 'carried', 'afya.medicine.service:MedicineService.restock_alerts', 'raised on the transition, not the state: a report that a medicine is in stock is not news unless the last thing anyone said was that it had run out'),
	('MED-004', 'Anti-gaming', 'Require location proximity to report', 'carried', 'afya.medicine.service:MedicineService.within_proximity', 'checked against the facility the report names, in the cell the client sends — a geohash rather than a coordinate, so §LOC-003\'s rule holds. A report with no geohash is accepted and recorded unweighted rather than refused: §13.2\'s `gps` fallback exists so a phone without a fix can still report'),
	('MED-004', 'Anti-gaming', 'Weight reports by reporter reliability', 'carried', 'afya.medicine.service:MedicineService.reporter_weight', 'derived from the reporter\'s history — a report a later one from someone else contradicts loses a point, one that stands gains one, the newest moves nothing — and never accepted from the client, because a client that sets its own weight has none. The reporter is bound to the token when the caller presents one, since the weight is only a weight if the history it reads belongs to one reporter and the route is ungated by design'),
	('MED-004', 'Anti-gaming', 'Show report age clearly', 'carried', 'afya.medicine.views:StockAvailability', '`age_hours` on every availability and `reported_at_iso` beside it, so the number and the fact it came from are both present'),
	# --- §9.4 FND-006: Appointment Booking and Queue Management ------------------------------
	('FND-006', 'Features', 'View available slots at participating facilities', 'carried', 'afya.facilities.views:SlotSchedule', 'a facility publishes what it will see people for; the day is served with the places already taken'),
	('FND-006', 'Features', 'Book, reschedule, cancel', 'carried', 'afya.facilities.service:FacilityService.reschedule', 'the owner is recorded from the token, so a move or a release is refused to anyone else'),
	('FND-006', 'Features', 'Queue number and estimated wait time', 'carried', 'afya.facilities.views:Booking', 'queue_position and wait_minutes'),
	('FND-006', 'Features', 'Check-in on arrival via QR code (see LOC-004)', 'carried', 'afya.location.service:LocationService.check_in', None),
	('FND-006', 'Features', 'Reminder notifications', 'carried', 'afya.facilities.views:Booking.reminder_due_iso', 'derived from the slot, so a reschedule cannot leave a reminder pointing at the old time'),
	# --- §9.5 INF-007: Service Status Feed ---------------------------------------------------
	('INF-007', 'Contents', 'School closures', 'carried', 'afya.alerts.views:ServiceStatus', 'a `school_closure` status with states open/closed, published by `AlertsService.publish_status` into §ALT-001\'s `service` feed category — the kind was already an `AlertKind` member and nothing produced one, so the status screen filtered an empty set'),
	('INF-007', 'Contents', 'border post status', 'carried', 'afya.location.service:LocationService.border_status', '§LOC-005\'s `BorderPost` — the name, the country pair, the queue time and whether screening is required; `border_post` is also a `ServiceStatus` kind with an `open/restricted/closed` state, which is what lets a restriction reach the same screen as a market closure'),
	('INF-007', 'Contents', 'market closures', 'carried', 'afya.alerts.views:ServiceStatus', 'a `market_closure` status carrying the market by name — the section says "market closures" and a status naming no market cannot answer whether it is the reader\'s market'),
	('INF-007', 'Contents', 'water interruptions', 'carried', 'afya.alerts.views:STATES_FOR', 'a `water_interruption` status with states interrupted/restored. Distinct from §MON-005\'s `water_quality` alert, which is about safety: water that is unsafe and water that is not running are two different answers and a single kind would conflate them'),
	('INF-007', 'Contents', 'road closures affecting facility access', 'carried', 'afya.alerts.views:ServiceStatus.model_post_init', 'a `road_closure` status with states open/restricted/closed, and the section\'s own qualifier is enforced: a road closure flagged as not affecting facility access is refused, because this feed exists to answer whether the reader can reach care'),
	('INF-007', 'Contents', 'public transport disruptions', 'carried', 'afya.alerts.views:ServiceStatus', 'a `transport_disruption` status with states normal/disrupted'),
	# --- §9.6 ALT-003: Personalised Alert Preferences ----------------------------------------
	('ALT-003', 'Options', 'County alerts', 'carried', 'afya.alerting.views:TOGGLEABLE', '`TOGGLEABLE` carries `county_alerts`; `AlertPreferences.enabled` is the per-person switch and `set_preference` writes it.'),
	('ALT-003', 'Options', 'disease-specific alerts', 'carried', 'afya.alerting.views:TOGGLEABLE', '`disease_alerts` is in `TOGGLEABLE`.'),
	('ALT-003', 'Options', 'facility alerts', 'carried', 'afya.alerting.views:TOGGLEABLE', '`facility_alerts` is in `TOGGLEABLE`.'),
	('ALT-003', 'Options', 'appointment reminders', 'carried', 'afya.alerting.views:TOGGLEABLE', '`appointment_reminders` is in `TOGGLEABLE`; no appointment producer publishes under it.'),
	('ALT-003', 'Options', 'medication reminders', 'carried', 'afya.alerting.views:TOGGLEABLE', '`medication_reminders` is in `TOGGLEABLE`; `MedReminder` exists and nothing raises an alert under it.'),
	('ALT-003', 'Options', 'immunisation reminders', 'carried', 'afya.alerting.views:TOGGLEABLE', '`immunisation_reminders` is in `TOGGLEABLE` and `FEED_PREFERENCE` maps the `immunisation` category to it; `publish_campaign` files campaign notices under that category, so the toggle has a producer and a parent who sets it receives them.'),
	('ALT-003', 'Options', 'community alerts', 'carried', 'afya.alerting.views:TOGGLEABLE', '`community_alerts` is in `TOGGLEABLE`.'),
	('ALT-003', 'Options', 'air quality alerts', 'carried', 'afya.alerting.views:TOGGLEABLE', '`air_quality` is in `TOGGLEABLE`.'),
	('ALT-003', 'Options', 'water quality alerts', 'carried', 'afya.alerting.views:TOGGLEABLE', '`water_quality` is in `TOGGLEABLE`; `AlertsService.water_alert` is the producer.'),
	# --- §10.1 REC-002: Family Health Wallet (Full) ------------------------------------------
	('REC-002', 'Additional features over REC-001', 'Encrypted cloud backup', 'carried', 'afya.records.service:RecordsService.backup', "the same service as REC-001's optional backup: consent-gated on `ConsentCategory.cloud_backup`, returning a `BackupEnvelope` whose `cipher`/`user_held_key` report what the deployment can actually do. §SEC-003's end-to-end encryption with a user-held key stays open and is named there, not closed by a boolean here."),
	('REC-002', 'Additional features over REC-001', 'Share with a specific provider for a limited time', 'carried', 'afya.records.service:RecordsService.grant_share', '`ShareGrant` carries a mandatory `expires_iso`, an optional named `recipient` and a `kinds` scope; `share_view` refuses past the expiry and `revoke_share` ends it early'),
	('REC-002', 'Additional features over REC-001', 'Provider-side view (for participating facilities)', 'carried', 'afya.records.service:RecordsService.share_view', '`GET /records/share/{grant_id}/view` is guarded on §17.4\'s `consented_patient` — the clinician row, "Patients who have consented to share" — so the share the patient issued is what makes the scope reachable and `rbac.unreachable_scopes` no longer lists it'),
	('REC-002', 'Additional features over REC-001', 'Timeline view of all health events', 'carried', 'afya.records.service:RecordsService.timeline', 'a sort over `WalletDocument` rather than a second store, covering every member `owns` admits and carrying `who` so a family timeline names the person each event belongs to'),
	('REC-002', 'Additional features over REC-001', 'Growth charts for children', 'carried', 'afya.records.growth:weight_reference', 'the child\'s series from `GrowthRecord` plotted against WHO reference lines computed from the published LMS parameters; `growth_standards.py` holds the tables and `sources/INDEX.md` records where they came from'),
	('REC-002', 'Additional features over REC-001', 'Vaccination certificates (for travel/school)', 'carried', 'afya.records.service:RecordsService.vaccination_certificate', 'rendered from the `ImmunisationRecord` dose log rather than a second store, so the certificate cannot disagree with the record; sealed with an HMAC over its own canonical fields and stating in `issuer` that it is a deployment seal, not a Ministry of Health signature'),
	('REC-002', 'Additional features over REC-001', 'Export to PDF for school, travel, or employment', 'carried', 'afya.records.pdf:render', 'a real PDF writer — no library is installed, so the format is written: header, numbered objects, a cross-reference table of true byte offsets, and Helvetica text with proper string escaping. `pdftotext` and `mutool` both read its output.'),
	# --- §10.1 REC-003: Growth and Development Tracker ---------------------------------------
	('REC-003', 'Features', 'Weight', 'carried', 'afya.records.growth:weight_z', "the `weight_kg` field scored against the WHO weight-for-age LMS parameters at the child's own month, so the verdict carries a magnitude and not only a word"),
	('REC-003', 'Features', 'height', 'carried', 'afya.records.growth:height_z', "`height_cm` scored against WHO, from the length-for-age table below 24 months and the height-for-age table at and above it — recumbent length and standing height differ by about 0.7 cm, so serving the wrong one is the wrong measurement rather than a rounding error"),
	('REC-003', 'Features', 'head circumference', 'carried', 'afya.records.growth:head_circumference_z', "`GrowthRecord.head_circumference_cm` existed and was read by nothing — the field a growth tracker takes in the first year, write-only. It now scores against WHO's head-circumference-for-age table (0-60 months, `L == 1` on every row, so the ordinary standard score) and travels on `GrowthAssessment` as `head_circumference_z` and `head_circumference_status`. An absent measurement stays `None` rather than defaulting to a z-score of 0, which would report an unmeasured child as exactly average"),
	('REC-003', 'Features', 'MUAC', 'carried', 'afya.records.growth:classify_muac', "`GrowthRecord.muac_mm` existed and was read by nothing. It now scores against WHO's arm-circumference-for-age table (3-60 months, `L != 1`, so the Box-Cox form is required) **and** is classified by Kenya's IMAM cut-offs — `<11.5` SAM, `11.5-12.4` MAM, `12.5-13.4` at-risk — which is a different instrument answering a different question from the z-score, and `MUAC_ALERTS` carries the guideline's own admission rule to the caregiver. The category starts at six months because Table 1.5 says \"children 6 to 59 months\" and refers an infant below that to the inpatient section; the z-score starts at three, where WHO's table does, so between the two a child has one and not the other"),
	('REC-003', 'Features', 'percentile charts', 'carried', 'afya.records.growth:weight_reference', '`RecordsService.growth_chart` draws the child\'s series against the WHO reference lines, and the lines are computed from the same LMS parameters as the child\'s own point, so the line a point is plotted against and the z-score reported for it cannot disagree — which is what happens when a chart uses WHO\'s printed rounded SD columns and the verdict uses the transform'),
	('REC-003', 'Features', 'undernutrition alerts', 'carried', 'afya.records.growth:MUAC_ALERTS', "the alert is the guideline's admission rule in the words a parent is given, keyed on the IMAM category rather than on a z-band, because the category is what a health worker acts on: SAM is unconditional admission, MAM routes to a feeding programme, at-risk to counselling. `normal` has no entry deliberately — a lookup returning a message for a healthy child turns the absence of a finding into a finding"),
	('REC-003', 'Features', 'feeding guidance by age', 'carried', 'afya.monitoring.service:MonitoringService.nutrition_guidance', 'bands by age, and since §MON-008 also by the month, so the guidance names what is in season'),
	('REC-003', 'Features', 'milestone checklists', 'carried', 'afya.records.views:MILESTONES', "Annex 9 of Kenya's IMAM guideline, 8 bands and 30 milestones, labelled in the guideline's own wording because the label is the sentence a caregiver is read. `RecordsService.milestone_check` applies Annex 9's ASSESS/CLASSIFY rules, which are three-valued with a precedence that is easy to collapse: DELAY needs a gap in the current band *and* an earlier one, or any regression; ALERT is a current-band gap alone; NORMAL is every current-band milestone present. The earlier bands are only counted when the caller says they were checked, because a caregiver asked only about their own age group supplied no evidence about the others and reading that silence as absence would classify every child as delayed"),
	# --- §10.1 REC-004: Menstrual and Reproductive Health Tracker ----------------------------
	('REC-004', 'Features', 'Period logging', 'carried', 'afya.women.views:CycleLog', 'the `start_iso` and `cycle_days` fields, written through `WomenService.log`'),
	('REC-004', 'Features', 'cycle prediction', 'carried', 'afya.women.service:WomenService.predict', 'calendar-method prediction over a median of logged cycles; `CyclePrediction.next_period_iso`'),
	('REC-004', 'Features', 'contraception reminders', 'carried', 'afya.women.service:WomenService.set_contraception', '`ContraceptionPlan` records the method against WHO\'s own table (`afya.women.content:CONTRACEPTIVE_METHODS`) and carries `next_due_iso`; `contraception_due` returns the ones whose date has arrived. Not a notification queue — the reminder is the date a client schedules locally, on §ACC-004\'s reasoning. `MedSchedule` stays a medication course and nothing keys it to a contraceptive.'),
	('REC-004', 'Features', 'fertility awareness', 'carried', 'afya.women.service:WomenService.predict', 'the window is a value on both spellings: `fertile_window_days` as the pair of cycle days and `fertile_from_iso`/`fertile_to_iso`/`ovulation_iso` as dates, derived from `LUTEAL_PHASE_DAYS` before the next period and `SPERM_SURVIVAL_DAYS` before that. `fertility_note` carries the source\'s own caveat and the statement that a calendar estimate is not a contraceptive method.'),
	('REC-004', 'Features', 'menopause support', 'carried', 'afya.women.service:WomenService.menopause', '`MenopauseStatus` runs the fact sheet\'s twelve-month rule over the person\'s own logs (`PERIMENOPAUSE_MONTHS`), names the source\'s symptom list verbatim and keeps `contraception_still_recommended` true through perimenopause. The 45–55 range is a population figure and is not applied to the person.'),
	('REC-004', 'Features', 'referral to services', 'carried', 'afya.women.service:WomenService.refer', '`ReproductiveReferral` names the services (`content.REFERRAL_SERVICES`) and lists by name the counselling lines whose numbers nobody verified — the same table §REC-005 and §INF-006 read, so a number cannot drift between the screens. `intermediaries.views:Referral` stays §CHAN-5\'s attribution record.'),
	# --- §10.1 REC-005: Mental Health Self-Check and Support ---------------------------------
	('REC-005', 'Features', 'PHQ-9 and GAD-7 screenings (validated, localised)', 'carried', 'afya.mental.service:MentalHealthService.screen', 'PHQ-9 and GAD-7 with the published item text, the four-point scale and the manual\'s cut-points, in `afya.mental.instruments`; served by `POST /mental/screen` and the item banks by `GET /mental/instruments`. Validated for the English forms; localised for PHQ-9 (the publisher\'s own Kiswahili edition is archived and served) and *not* for GAD-7, which the publisher ships in 41 languages and not Swahili — the service serves English there and names the substitution rather than labelling English items `sw`'),
	('REC-005', 'Features', 'Mood tracking', 'carried', 'afya.mental.service:MentalHealthService.mood_trend', '`MoodEntry` is a person\'s own 0–10 daily reading, kept apart from the instrument scales because averaging a self-rating with a scored instrument produces a number with neither property; `mood_trend` returns a direction or the named `too_few` — two readings are not a steady mood. `POST /mental/mood`, `GET /mental/mood/trend`'),
	('REC-005', 'Features', 'Coping strategies and psychoeducation', 'carried', 'afya.mental.service:coping_strategies', 'Six strategies from WHO\'s *Psychological first aid: guide for field workers* (`sources/who-pfa/`), in the source\'s own English **and Kiswahili** editions, so the Kiswahili is the publisher\'s text rather than a rendering of the English. The source\'s line that PFA "is not \'psychological debriefing\'" and "is not about pressuring people to tell you their feelings" is enforced on the content, not merely respected. `GET /mental/coping`'),
	('REC-005', 'Features', 'Referral to services', 'carried', 'afya.mental.service:MentalHealthService.refer', '`refer` builds a record that names the services, keeps the person\'s own reason, and lists by name the lines whose numbers are unverified (`COUNSELLING_LINES` marks all three `verified: \'False\'`) — a referral to a number nobody checked is worse than none, because the person stops looking. `POST /mental/referral`, self-scoped'),
	('REC-005', 'Features', 'Crisis line access', 'carried', 'afya.mental.service:MentalHealthService.lines', '`COUNSELLING_LINES` — Befrienders Kenya, NACADA 1192 and the 1199/719 emergency row — served by `/mental/lines`, and reached from every screening whose self-harm item is positive'),
	('REC-005', 'Features', 'Outbreak-specific: isolation distress, grief support, healthcare worker burnout', 'carried', 'afya.mental.service:guidance_for', 'The section\'s own three, as named conditions with signs and a route rather than a band on a total: "your score is 14" does not tell someone in isolation that what they feel has a name. Grief is explicitly not medicalised (the source lists it among expected reactions), and the worker content points staff at the same lines they send others to. `GET /mental/outbreak-support/{condition}`'),
	# --- §10.1 REC-006: Blood Donor Matching -------------------------------------------------
	('REC-006', 'Features', 'Register as a donor (blood group, location, availability)', 'carried', 'afya.blood.service:BloodService.register', '`Donor` carries `blood_group`, `county` and `last_donation_iso`; "availability" is the eligibility the date implies rather than a field'),
	('REC-006', 'Features', 'Receive alerts when your blood type is urgently needed nearby', 'carried', 'afya.blood.views:BloodService.donor_alerts', '`donor_alerts` answers the donor\'s question rather than the requester\'s: `URGENCY_REACH` widens the counties in hops (0 = the request\'s own, 1 = the ones that touch it, 2 = the ones that touch those, over §INF-001\'s table) and `URGENCY_DEPTH` widens the groups, so a `routine` need notifies the exact group in its own county, an `urgent` one the compatible groups next door, and a `critical` one two counties out. The 90-day interval keeps an ineligible donor out — an alert is an invitation to donate. `POST /blood/alerts`'),
	('REC-006', 'Features', 'Find donation centres', 'carried', 'afya.blood.views:BloodService.donation_centres', '`PlaceKind.blood_donation` and `PlaceKind.blood_bank`, from OpenStreetMap\'s `healthcare` key (`sources/osm-healthcare-tags/`); the finder defaults to `blood_donation` because a storage site is not somewhere a donor can go, and the importer reads both keys. `GET /blood/donation-centres`'),
	('REC-006', 'Features', 'Donation history and eligibility tracker', 'carried', 'afya.blood.service:BloodService.record_donation', '`record_donation` stamps `last_donation_iso` and `_eligible` applies the 90-day `DONATION_INTERVAL_DAYS`; the "history" is that single date, not a list of donations'),
	('REC-006', 'Features', 'Emergency requests from facilities', 'carried', 'afya.blood.views:BloodRequest', '`BloodRequest` carries `blood_group`, `county` and `urgency` (routine|urgent|critical) and `/blood/match` serves it'),
	# --- §10.2 MON-005: Water Quality Alerts -------------------------------------------------
	('MON-005', 'Features', 'Boil-water notices', 'carried', 'afya.alerts.service:AlertsService.water_alert', '`WaterQuality.unsafe` decides it and the advisory reads "do not drink without boiling"'),
	('MON-005', 'Features', 'contamination reports', 'carried', 'afya.alerts.views:WaterQuality', '`ecoli_detected` and `turbidity_ntu` are the two contaminants; the reading is an input the county posts and no user report reaches the model'),
	('MON-005', 'Features', 'treatment guidance', 'carried', 'afya.alerts.service:AlertsService.treatment_guidance', 'the methods the reading permits, each with its steps and its stated limit; chlorine is withheld above the turbidity its own evaluation allows'),
	('MON-005', 'Features', 'safe storage guidance', 'carried', 'afya.alerts.views:StorageGuidance', 'one block per permitted method, with the residual that protects stored chlorinated water and none for boiled water'),
	('MON-005', 'Features', 'point-of-use treatment reminders', 'carried', 'afya.alerts.service:AlertsService.treatment_reminder', 'derived from the time the household treats water, on the storage guidance\'s own one-day interval; absent when the household has not said when'),
	# --- §10.2 MON-006: Air Quality Index ----------------------------------------------------
	('MON-006', 'Features', "AQI for user's location", 'carried', 'afya.alerts.views:pm25_aqi', 'the index is computed from `AirQuality.pm25` by the source\'s own breakpoint table and interpolation; `AlertsService.air_reading` pairs it with the category and the place the caller names'),
	('MON-006', 'Features', 'health advisories for sensitive groups', 'carried', 'afya.alerts.service:AlertsService.air_alert', 'the watch and alert branches address "sensitive groups"; `AirQuality.band` fixes the three bands, now read off the index so the advisory and the index cannot disagree'),
	('MON-006', 'Features', 'mask guidance', 'carried', 'afya.alerts.service:AlertsService.mask_guidance', 'the alert branch names what to wear and states what a mask does not do — WHO\'s guidelines defer this to another document, so the text is the repo\'s own'),
	('MON-006', 'Features', 'best times for outdoor activity', 'carried', 'afya.alerts.service:AlertsService.outdoor_window', 'the cleanest hours of the day from the caller\'s hourly series; every hour at the best level, ordered, and the advice says when no hour is actually clean'),
	('MON-006', 'Features', 'pollution source information', 'carried', 'afya.alerts.service:AlertsService.pollution_source', 'the WHO source categories, named only where the caller reports evidence for one; with none reported the list is empty and `evidence` says the source is not known'),
	# --- §10.2 MON-007: Vector and Environmental Risk ----------------------------------------
	('MON-007', 'Features', 'Malaria season alerts by region', 'carried', 'afya.monitoring.service:MonitoringService.vector_risk', "`VectorRisk.malaria_season` from the county's 72-hour rainfall; the region is the county the caller passes, and no seasonal calendar is carried — the band is the recent rain"),
	('MON-007', 'Features', 'mosquito breeding site reporting', 'carried', 'afya.monitoring.service:MonitoringService.report_breeding_site', 'routed to the county public health office; `community.IssueKind.mosquito_breeding` is the same report in the issue catalogue'),
	('MON-007', 'Features', 'larviciding campaign notifications', 'carried', 'afya.monitoring.service:MonitoringService.publish_larviciding', 'the round is published into §ALT-001\'s feed under the new `vector_control` category, which `FEED_PREFERENCE` routes to §ALT-003\'s existing "County alerts" preference — no twelfth toggle is invented. `LARVICIDE_CLASSES` carries the re-treatment interval per class from the WHO larval source management manual, `SUPPLEMENT_RULE` is appended to every body so the notice can never claim larviciding replaces nets or spraying, and `/monitoring/larviciding/{county}` serves the rounds a county has issued'),
	('MON-007', 'Features', 'personal protection reminders', 'carried', 'afya.monitoring.service:MonitoringService.protection_reminder', '`ProtectionReminder` schedules the two acts the section names. The net reminder is anchored at the next dusk, because the manual puts anopheline biting "between dusk and dawn"; the container reminder is `LARVICIDE_INTERVAL_FLOOR_DAYS` out, derived from `LARVICIDE_CLASSES` so a household is asked to clear standing water at least as often as a county would re-treat it. The message varies with the four rain bands, which `_rainfall_band` now defines once for this and `vector_risk` alike'),
	('MON-007', 'Features', 'Rift Valley fever alerts for livestock-adjacent communities', 'carried', 'afya.monitoring.service:MonitoringService.vector_risk', '`VectorRisk.rvf_alert` where `livestock_adjacent` and the rain band is wet or flood'),
	# --- §10.2 MON-008: Nutrition and Food Safety --------------------------------------------
	('MON-008', 'Features', 'Seasonal food availability', 'carried', 'afya.monitoring.views:SEASONAL_FOODS', 'the harvest windows are the FAO Crop Calendar for Kenya\'s own data, generated rather than typed: 29 crops with a stated harvest month plus the 5 the source flags `all_year`, each row carrying the source\'s own crop name beside the English label so the rendering is checkable. `NutritionGuidance.in_season` answers it for a month and `calendar_source` names the provenance. Two limits are the source\'s and are recorded rather than papered over: the data is disaggregated by agro-ecological zone so a month means "harvested somewhere in Kenya", and avocado, mango, banana, amaranth and fish are absent from it and therefore absent from the table'),
	('MON-008', 'Features', 'aflatoxin alerts', 'carried', 'afya.monitoring.views:FoodSafetyAlert', '`kind` accepts `aflatoxin`; `issue_food_alert` stores it and `/monitoring/food-alerts/{county}` serves it'),
	('MON-008', 'Features', 'food recall notifications', 'carried', 'afya.monitoring.views:FoodSafetyAlert', '`kind` accepts `recall`; the feed is pulled rather than pushed — `/monitoring/food-alerts/{county}` returns what a county issued, and nothing notifies'),
	('MON-008', 'Features', 'infant feeding guidance', 'carried', 'afya.monitoring.service:MonitoringService.nutrition_guidance', '`NUTRITION_BY_AGE` bands 0-60 months and `/monitoring/nutrition/{age_months}` serves it'),
	('MON-008', 'Features', 'therapeutic feeding programme locations', 'carried', 'afya.monitoring.service:MonitoringService.therapeutic_feeding_centres', '`FacilityKind.therapeutic_feeding` is the sixth member and `/monitoring/therapeutic-feeding` lists the sites nearest a position, filtered to the county. The vocabulary is Kenya\'s IMAM guideline, not OpenStreetMap: there is no OSM tag for a therapeutic feeding centre, so `IMAM_PROGRAMMES` carries the guideline\'s own `OTP`/`SC`/`SFP` and their admission criteria with every result. The programmes travel as the national vocabulary and not as a per-site claim, because the registry records *that* a facility is a therapeutic feeding site and not which of the three it runs'),
	('MON-008', 'Features', 'recipe ideas for local ingredients', 'carried', 'afya.monitoring.service:NUTRITION_BY_AGE', 'each band carries a local-food list — ugali, sukuma wiki, githeri — which is the ingredient side of a recipe with no method attached'),
	# --- §10.3 ALT-001: Community Alert Feed -------------------------------------------------
	('ALT-001', 'Contents', 'Disease outbreaks', 'carried', 'afya.alerting.views:FEED_CATEGORIES', 'the `outbreak` category; §6.4 corrections publish into it'),
	('ALT-001', 'Contents', 'weather emergencies', 'carried', 'afya.alerting.views:FEED_CATEGORIES', 'the `weather` category, routed to `county_alerts`'),
	('ALT-001', 'Contents', 'floods', 'carried', 'afya.alerting.views:FEED_CATEGORIES', 'the `flood` category, routed to `county_alerts`'),
	('ALT-001', 'Contents', 'fires', 'carried', 'afya.alerting.views:FEED_CATEGORIES', 'the `fire` category, routed to `county_alerts`'),
	('ALT-001', 'Contents', 'road closures', 'carried', 'afya.alerting.views:FEED_CATEGORIES', 'the `road` category, routed to `county_alerts`'),
	('ALT-001', 'Contents', 'security incidents affecting health access', 'carried', 'afya.alerting.views:FEED_CATEGORIES', 'the `security` category, routed to `county_alerts`'),
	('ALT-001', 'Contents', 'drug recalls', 'carried', 'afya.alerting.views:FEED_CATEGORIES', 'the `drug_recall` category, routed to `facility_alerts`'),
	('ALT-001', 'Contents', 'water notices', 'carried', 'afya.alerting.views:FEED_CATEGORIES', 'the `water` category, routed to `water_quality`'),
	('ALT-001', 'Contents', 'food recalls', 'carried', 'afya.alerting.views:FEED_CATEGORIES', 'the `food_recall` category, routed to `nutrition`'),
	# --- §10.3 ALT-002: Family Safety Check-In -----------------------------------------------
	('ALT-002', 'Features', '"I\'m safe" button that notifies linked family members', 'carried', 'afya.alerting.service:AlertingService.check_in', 'the button is the client surface; `check_in` records the timestamp and `family_board` derives the safe/unknown split — the "notify" is the board a member reads, not a message sent'),
	('ALT-002', 'Features', 'Family status board during an active alert', 'carried', 'afya.alerting.service:AlertingService.family_board', '`FamilyStatus` carries `members_safe`/`members_unknown` and a rendered `board` string'),
	('ALT-002', 'Features', "Automatic check-in prompts during a declared emergency in the user's area", 'deferred', None, "a check-in prompt is a client notification surface, and the clause is conditioned on a declared emergency in the user's area — a fact about the world rather than this tree; the server carries the board and the check-in, and nothing schedules a prompt"),
	('ALT-002', 'Features', 'Works over SMS when data is unavailable', 'carried', 'afya.alerting.service:AlertingService.check_in_by_msisdn', "Both directions are carried: the check-in texts every member who has not answered through §5.3's channel service, and an inbound body matching `afya.strings:SMS_SAFE_KEYWORDS` is filed as a check-in from the sender's own number — so a person on a feature phone with no data reaches the same board as one pressing the button."),
	# --- §10.4 COM-005: Community Reporting --------------------------------------------------
	('COM-005', 'Reportable items', 'Broken water point', 'carried', 'afya.community.views:IssueKind', '`IssueKind.broken_water_point`; `ISSUE_ROUTING` routes it to County Water Services and `CommunityService.report_issue` writes it.'),
	('COM-005', 'Reportable items', 'open sewage', 'carried', 'afya.community.views:IssueKind', '`IssueKind.open_sewage`, routed to the County Public Health Office.'),
	('COM-005', 'Reportable items', 'illegal dumping', 'carried', 'afya.community.views:IssueKind', '`IssueKind.illegal_dumping`, routed to the County Environment Office.'),
	('COM-005', 'Reportable items', 'mosquito breeding site', 'carried', 'afya.community.views:IssueKind', '`IssueKind.mosquito_breeding`.'),
	('COM-005', 'Reportable items', 'dead animal', 'carried', 'afya.community.views:IssueKind', '`IssueKind.dead_animal`.'),
	('COM-005', 'Reportable items', 'unsafe food vendor', 'carried', 'afya.community.views:IssueKind', '`IssueKind.unsafe_food_vendor`.'),
	('COM-005', 'Reportable items', 'suspected counterfeit medicine', 'carried', 'afya.community.views:IssueKind', '`IssueKind.counterfeit_medicine`.'),
	('COM-005', 'Reportable items', 'facility stockout', 'carried', 'afya.community.views:IssueKind', '`IssueKind.facility_stockout`.'),
	('COM-005', 'Reportable items', 'facility staff absence', 'carried', 'afya.community.views:IssueKind', '`IssueKind.facility_staff_absence`.'),
	# --- §10.5 INF-008: Health Tips and Education --------------------------------------------
	('INF-008', 'Format', 'Short cards', 'carried', 'afya.info.content_seed:seed_rows', "`ContentFormat.card` is the format `afya.info.content_seed:seed_rows` gives every `tips`-tagged row, and the model's `is_text` property is what says a card is prose rather than a rendition — the format the section prints, as a value the report can count."),
	('INF-008', 'Format', '30-second videos', 'carried', 'afya.info.content_seed:seed_rows', '`ContentFormat.video` with its `media_ref` on the `tips`-tagged corpus; `format_coverage()` reports the format delivered.'),
	('INF-008', 'Format', 'audio clips', 'carried', 'afya.info.content_seed:seed_rows', '`ContentFormat.audio` with its `media_ref` on the `tips`-tagged corpus; `format_coverage()` reports the format delivered.'),
	('INF-008', 'Topics', 'Hygiene', 'carried', 'afya.info.content_seed:seed_rows', '`HEALTH_TIP_TOPICS` names the topic and the `health-tips-hygiene` card answers it; `coverage()` reports it covered against the `tips`-tagged corpus.'),
	('INF-008', 'Topics', 'nutrition', 'carried', 'afya.info.content_seed:seed_rows', '`HEALTH_TIP_TOPICS` names the topic and the `health-tips-nutrition` card answers it; `coverage()` reports it covered against the `tips`-tagged corpus.'),
	('INF-008', 'Topics', 'mental health', 'carried', 'afya.info.content_seed:seed_rows', '`HEALTH_TIP_TOPICS` names the topic and the `health-tips-mental-health` card answers it; `coverage()` reports it covered against the `tips`-tagged corpus.'),
	('INF-008', 'Topics', 'first aid', 'carried', 'afya.info.content_seed:seed_rows', '`HEALTH_TIP_TOPICS` names the topic and the `health-tips-first-aid` card answers it; `coverage()` reports it covered against the `tips`-tagged corpus.'),
	('INF-008', 'Topics', 'child development', 'carried', 'afya.info.content_seed:seed_rows', '`HEALTH_TIP_TOPICS` names the topic and the `health-tips-child-development` card answers it; `coverage()` reports it covered against the `tips`-tagged corpus.'),
	('INF-008', 'Topics', 'chronic disease management', 'carried', 'afya.info.content_seed:seed_rows', '`HEALTH_TIP_TOPICS` names the topic and the `health-tips-chronic-disease` card answers it; `coverage()` reports it covered against the `tips`-tagged corpus.'),
	('INF-008', 'Topics', 'injury prevention', 'carried', 'afya.info.content_seed:seed_rows', '`HEALTH_TIP_TOPICS` names the topic and the `health-tips-injury-prevention` card answers it; `coverage()` reports it covered against the `tips`-tagged corpus.'),
	('INF-008', 'Topics', 'sexual and reproductive health', 'carried', 'afya.info.content_seed:seed_rows', '`HEALTH_TIP_TOPICS` names the topic and the `health-tips-srh` card answers it; `coverage()` reports it covered against the `tips`-tagged corpus.'),
	# --- §10.5 INF-009: First Aid Guide ------------------------------------------------------
	('INF-009', 'Topics', 'Bleeding', 'carried', 'afya.info.content_seed:seed_rows', "The `first-aid-bleeding` item is the `first-aid`-tagged corpus's guidance for it; `FIRST_AID_TOPICS` names the topic and `coverage()` reads the item's own words for it."),
	('INF-009', 'Topics', 'burns', 'carried', 'afya.info.content_seed:seed_rows', "The `first-aid-burns` item is the `first-aid`-tagged corpus's guidance for it; `FIRST_AID_TOPICS` names the topic and `coverage()` reads the item's own words for it."),
	('INF-009', 'Topics', 'choking', 'carried', 'afya.info.content_seed:seed_rows', "The `first-aid-choking` seed item is the one `first-aid`-tagged item in the corpus, and `coverage()` reads it as covering 'choking'."),
	('INF-009', 'Topics', 'drowning', 'carried', 'afya.info.content_seed:seed_rows', "The `first-aid-drowning` item is the `first-aid`-tagged corpus's guidance for it; `FIRST_AID_TOPICS` names the topic and `coverage()` reads the item's own words for it."),
	('INF-009', 'Topics', 'fractures', 'carried', 'afya.info.content_seed:seed_rows', "The `first-aid-fractures` item is the `first-aid`-tagged corpus's guidance for it; `FIRST_AID_TOPICS` names the topic and `coverage()` reads the item's own words for it."),
	('INF-009', 'Topics', 'poisoning', 'carried', 'afya.info.content_seed:seed_rows', "The `first-aid-poisoning` item is the `first-aid`-tagged corpus's guidance for it; `FIRST_AID_TOPICS` names the topic and `coverage()` reads the item's own words for it."),
	('INF-009', 'Topics', 'snakebite', 'carried', 'afya.info.content_seed:seed_rows', "The `first-aid-snakebite` item is the `first-aid`-tagged corpus's guidance for it; `FIRST_AID_TOPICS` names the topic and `coverage()` reads the item's own words for it."),
	('INF-009', 'Topics', 'seizure', 'carried', 'afya.info.content_seed:seed_rows', "The `first-aid-seizure` item is the `first-aid`-tagged corpus's guidance for it; `FIRST_AID_TOPICS` names the topic and `coverage()` reads the item's own words for it."),
	('INF-009', 'Topics', 'unconsciousness', 'carried', 'afya.info.content_seed:seed_rows', "The `first-aid-unconsciousness` item is the `first-aid`-tagged corpus's guidance for it; `FIRST_AID_TOPICS` names the topic and `coverage()` reads the item's own words for it."),
	('INF-009', 'Topics', 'CPR', 'carried', 'afya.info.content_seed:seed_rows', "The `first-aid-cpr` item is the `first-aid`-tagged corpus's guidance for it; `FIRST_AID_TOPICS` names the topic and `coverage()` reads the item's own words for it."),
	('INF-009', 'Topics', 'shock', 'carried', 'afya.info.content_seed:seed_rows', "The `first-aid-shock` item is the `first-aid`-tagged corpus's guidance for it; `FIRST_AID_TOPICS` names the topic and `coverage()` reads the item's own words for it."),
	# --- §10.5 INF-010: Safe and Dignified Burial Guidance -----------------------------------
	('INF-010', 'Content', 'Why safe burial matters for Ebola', 'carried', 'afya.info.content_seed:seed_rows', "The `safe-burial` seed item's body states that traditional washing of EVD bodies spreads the virus, which is why safe burial matters; `coverage()` reads the item as covering this point."),
	('INF-010', 'Content', 'How to conduct a safe and dignified burial', 'carried', 'afya.info.content_seed:seed_rows', 'The item points at WHO burial-team protocol and says dignity is preserved; `coverage()` reads it as covering the point, though the item is one sentence.'),
	('INF-010', 'Content', 'Who to contact (burial team)', 'carried', 'afya.info.content_seed:seed_rows', 'The `burial-contact-team` item names the public-health burial team and the district number to call; the older `safe-burial` item was credited here by mistake — it names burial teams but never says who to *contact*, and the sibling-word rule in `covers()` drops "burial" because all six topics share it, so it never covered this point.'),
	('INF-010', 'Content', 'Cultural and religious considerations', 'carried', 'afya.info.content_seed:seed_rows', "The `burial-cultural-religious` item is the guidance: burial teams work within the family's practice, and `coverage()` reads the point covered against the `burial`-tagged corpus."),
	('INF-010', 'Content', 'Support for grieving families', 'carried', 'afya.info.content_seed:seed_rows', 'The `burial-grieving-families` item covers the compounded grief, the quarantine the family may have been in, and the psychosocial follow-up.'),
	('INF-010', 'Content', 'What happens if the family cannot conduct the burial themselves', 'carried', 'afya.info.content_seed:seed_rows', 'The `burial-family-cannot` item says the burial team performs the burial, the family is told where the grave is, and no family is left without a grave to visit.'),
	# --- §11.2 TRI-003: Ebola-Specific Triage ------------------------------------------------
	('TRI-003', 'Additional inputs', 'Specific exposure history (funeral attendance, healthcare work, contact with a case, consumption of bushmeat)', 'carried', 'afya.triage.views:EBOLA_EXPOSURES', None),
	('TRI-003', 'Additional inputs', 'Vaccination status (if a vaccine is available and deployed)', 'deferred', None, 'the section conditions this on a vaccine being deployed, which is a fact about the world rather than about this tree — nothing here can carry it until one is'),
	('TRI-003', 'Additional inputs', 'Isolation status', 'carried', 'afya.triage.views:ISOLATION_STATES', None),
	('TRI-003', 'Outputs', 'Ebola suspicion classification', 'carried', 'afya.triage.service:TriageService.assess_evd', None),
	('TRI-003', 'Outputs', 'Immediate action (call 719, do not travel by public transport, await instructions)', 'carried', 'afya.triage.service:_immediate_actions', None),
	('TRI-003', 'Outputs', 'Isolation guidance for the household', 'carried', 'afya.triage.service:_household_isolation', None),
	('TRI-003', 'Outputs', 'Contact list building (see COM-103)', 'carried', 'afya.community.service:CommunityService.add_contact', None),
	# --- §11.3 MON-009: 21-Day Contact Monitoring Diary --------------------------------------
	('MON-009', 'Features', 'Daily temperature logging (manual or via Bluetooth thermometer)', 'carried', 'afya.monitoring.views:MonitoringDay', '`temperature_c` is required on every entry and `source` is a `MeasurementSource`, so a typed reading and a paired `ble_device` one are told apart (§14.9)'),
	('MON-009', 'Features', 'Symptom checklist (fever, fatigue, muscle pain, headache, sore throat, vomiting, diarrhoea, rash, bleeding)', 'carried', 'afya.monitoring.service:MONITORING_ALERT_SYMPTOMS', 'the constant is exactly those nine plus `hiccups`, and `log_day` intersects the entry with it'),
	('MON-009', 'Features', 'Twice-daily reminders', 'carried', 'afya.monitoring.service:MonitoringService.reminders', '`ReminderSlot` names the two slots a day has and `reminders` reports which are in, which are missing and the §11.3 escalation rung; `_day_complete` counts a half-kept day as missed, so the ladder fires for the person who logs every morning and forgets every evening'),
	('MON-009', 'Features', 'Visual countdown to the end of the 21-day period', 'carried', 'afya.monitoring.views:MonitoringVerdict', '`days_remaining` = `MONITORING_DAYS` - `day` and `day` is bounded 1–21'),
	('MON-009', 'Features', '**Escalation logic:** Any fever or new symptom triggers an immediate prompt to call 719 and, with consent, notifies the assigned CHW or county team', 'carried', 'afya.monitoring.service:MonitoringService.log_day', '`log_day` escalates on a fever (>=38.0 °C) or any alert symptom and sets `notify_chw` when an officer is named — but `notify_chw` is a bool and no CHW is notified'),
	('MON-009', 'Features', 'Location logging (with consent) to support contact tracing', 'carried', 'afya.monitoring.service:MonitoringService.record_location_consent', 'consent is a dated, revocable decision on the household — `granted` both ways — and `log_day` refuses an entry claiming a location without it, so the flag is the person\'s and not the client\'s'),
	('MON-009', 'Features', 'Household member monitoring in the same interface', 'carried', 'afya.monitoring.service:MonitoringService.member_diary', 'members are added to the household and a day filed for one is read back through `member_diary`; `diary`, `_slots_logged` and `adherence_reminder_days` all exclude member entries, so a member\'s fever is never the contact\'s'),
	('MON-009', 'Features', 'Psychological support resources', 'carried', 'afya.monitoring.service:support_resources', 'every verdict carries the §REC-005 counselling lines read from the one place they live, plus coping and outbreak-support routes, and a flagged verdict leads with a note saying why they are on the screen'),
	('MON-009', 'Features', 'Direct line to the assigned monitoring officer', 'carried', 'afya.monitoring.service:MonitoringService.monitoring_officer_line', 'the officer carries a number and the line is a `tel:` target; a name with no number behind it is named and falls back to 719 rather than serving a dead button'),
	# --- §11.4 COM-101: Community Health Worker Reporting Module -----------------------------
	('COM-101', 'Features', 'Guided case report form based on WHO IDSR and Kenya MoH standards', 'carried', 'afya.community.views:CaseReport', 'the structured report the docstring names; WHO IDSR / MoH standards are the design commitment behind the field set'),
	('COM-101', 'Features', 'Patient demographics (name optional; can be anonymous)', 'carried', 'afya.community.views:CaseReport', '`patient_ref` is optional and `age_years`/`sex` are the demographics, so anonymous is a first-class path'),
	('COM-101', 'Features', 'Symptom checklist', 'carried', 'afya.community.views:CaseReport', 'the `symptoms` list, min_length 1'),
	('COM-101', 'Features', 'Exposure history', 'carried', 'afya.community.views:CaseReport', 'the `exposure_history` field'),
	('COM-101', 'Features', '**Geotagged photo capture** (with consent) of visible symptoms', 'deferred', None, 'capturing a photo is a device action; the client does it and `CaseReport` carries the `photo_sha256` it yields, gated on `geotagged` consent'),
	('COM-101', 'Features', '**Voice-to-text notes** in local languages', 'carried', 'afya.community.views:CaseReport', '`voice_note` carries the transcript and `voice_note_lang` the language it was said in, asserted paired so a note cannot arrive with one and not the other; the transcription itself is §ACC-002\'s `AccessService.transcribe_audio`, which keeps a `purpose=note` dictation as text instead of triaging it. "In local languages" is bounded by `LANGUAGE_MATRIX.asr`: notes are recognised in `en` and `sw` only'),
	('COM-101', 'Features', '**Offline report queue** — reports stored locally and submitted when connectivity is available', 'carried', 'afya.community.service:CommunityService._queue_case', "`submit_case` writes the report to the deployment's queue when the CHW declares `reported_offline`, under §16.3's own `case_reports` rule (server-authoritative), so the strategy on replay is the spec's rather than one chosen at the call site. The whole report travels as the payload — §16.4's delta is computed field by field, so `None` is encoded rather than omitted, which is what keeps \"unchanged\" and \"cleared\" distinguishable on the wire. The queue is injected by the composition root, so a route cannot file a report and lose it, and the op id is taken from the *tail* of the UUID7 because a prefix collides for two reports filed in the same millisecond — the burst a CHW replays after an outage"),
	('COM-101', 'Features', 'Automatic alerts to the appropriate disease surveillance officer on submission (mirroring AVADAR)', 'carried', 'afya.community.service:CommunityService.submit_case', 'returns `alerts_sent=1` on the first submission; a duplicate open case is told no second alert was sent'),
	('COM-101', 'Features', 'Case status tracking (reported → investigated → lab result → closed)', 'carried', 'afya.community.views:CaseStatus', 'the four-member enum; `advance_case` enforces forward-only movement'),
	('COM-101', 'Features', 'PPE reminders and guidance', 'carried', 'afya.community.service:CommunityService.ppe_reminder', 'the donning/doffing guidance string, served by `/community/ppe-reminder`'),
	('COM-101', 'Features', 'Reference materials and job aids', 'carried', 'afya.chw.views:JOB_AIDS', 'six topics served by `/chw/job-aid/{topic}`'),
	('COM-101', 'Features', 'Daily activity log for supervision', 'carried', 'afya.chw.service:ChwService.activity_summary', '`ActivityLogEntry` is written by `/chw/activity` and the summary groups by activity kind'),
	# --- §11.4 COM-102: Peer-to-Peer Community Alert Network ---------------------------------
	('COM-102', 'Features', 'Geofenced alert zones (500 m, 1 km, 5 km — configurable by county)', 'carried', 'afya.location.service:ALLOWED_RADII_M', 'the `(500, 1000, 5000)` radii, re-exported from `afya.location.views:ALERT_ZONE_RADII_M` with an identity assert, and `PeerAlert.model_post_init` validates `radius_m` against the set rather than a range — 3000 m is refused'),
	('COM-102', 'Features', 'Alert content: "A suspected case has been reported in your area. Avoid [specific location]. Monitor for symptoms for 21 days. Call 719 if you feel unwell."', 'carried', 'afya.community.views:ALERT_TEMPLATE', 'the section sentence is the template and `PeerAlert.body` is a computed field over it, so the only slot is `location` and a free-text body is not representable; `DerivedFields` drops a caller-supplied `body` on the way in'),
	('COM-102', 'Features', 'No personally identifiable information about the case', 'carried', 'afya.community.views:PeerAlert', 'enforced by construction (the template has nowhere to put an identifier) and by a `location` shape check that refuses dwelling-plus-number and determiner-plus-person-noun; "the case" is deliberately allowed, since it names nobody and banning it would refuse "The Case Hotel"'),
	('COM-102', 'Features', 'Users acknowledge alerts and receive follow-up guidance', 'carried', 'afya.community.service:CommunityService.acknowledge_peer_alert', '`PeerAlertAck` is posted to `/community/peer-alert/ack`, which binds `subject_ref` to the token via `require_self` (403 on a mismatch), and returns `PeerAlertGuidance` with `ALERT_GUIDANCE`; the receipt counts distinct subjects'),
	('COM-102', 'Features', 'Follow-up prompts on days 3, 7, 14, and 21', 'carried', 'afya.community.service:CommunityService.followup_prompt', 'reads `FOLLOWUP_DAYS` on a day passed in rather than a clock and returns `None` on any other day; `PeerAlert.model_post_init` pins `followup_days` to the same four, so a caller cannot add a fifth'),
	# --- §11.4 COM-103: Contact-Tracing Assistance for Individuals ---------------------------
	('COM-103', 'Features', 'Guided prompts based on call logs, calendar events, and location history (with full consent)', 'deferred', None, 'reading call logs, calendar and location history is a device permission; the server carries `TRACING_PROMPTS` and takes no device feed'),
	('COM-103', 'Features', 'Simple form to list names and contact details', 'carried', 'afya.community.views:ContactEntry', '`description` is the name/description and `contact_ref` the contact detail'),
	('COM-103', 'Features', '"I don\'t know their name" option — record a description and approximate location instead', 'carried', 'afya.community.views:ContactEntry', '`name_unknown` with `approx_location`'),
	('COM-103', 'Features', 'Categorised by setting (home, work, transport, worship, market, social)', 'carried', 'afya.community.views:ContactEntry', 'the `setting` pattern, which adds `other`'),
	('COM-103', 'Features', 'Option to share with health authorities through a secure, encrypted channel', 'carried', 'afya.community.service:CommunityService.share_contacts', 'sealed under §SEC-003\'s *application-layer* key before it leaves the process, so the wire carries ciphertext and the at-rest key an operator holds does not open it; the share is refused rather than sent in the clear when that key is absent. Gated on `share_consent` and on a non-empty list, and `ContactTracingSummary.shared` now reports whether a share actually left rather than whether the flag was set — the audit row\'s own defect, where the person was told "Shared with the health team." with nothing sent. Travels the ADaM wire (`AdamClient.share_contact_list`) and is kept in the service\'s outbox when no transport is wired, with the receipt saying held rather than delivered'),
	('COM-103', 'Features', 'Progress indicator', 'carried', 'afya.community.service:CommunityService.summary', '`progress_pct` over `TRACING_PROMPTS`, returned by both contact routes'),
	# --- §11.4 COM-104: Community Misinformation Tracker -------------------------------------
	('COM-104', 'Features', 'Simple "Report misinformation" button', 'carried', 'afya.community.views:MisinfoSubmission', 'the `flag_misinformation` mobile action posts to `/community/misinformation`'),
	('COM-104', 'Features', 'Text, voice, or screenshot submission', 'carried', 'afya.community.views:MisinfoSubmission', '`evidence_ref` carries the recording or the image and `transcript` the words a voice note said, both required for the three media that name one — a `screenshot` report with no image was indistinguishable from a `text` one while the cluster counts read "12 screenshots". The bytes stay out of the model: §SEC-002\'s "Photos encrypted and only shared with explicit per-item consent" is `evidence_consent`, given per report rather than once at install, and the reference points at an envelope the caller sealed under §SEC-003\'s application-layer key'),
	('COM-104', 'Features', 'Aggregation by topic and location', 'carried', 'afya.community.service:CommunityService.clusters', '`MisinfoCluster` groups by topic and carries the counties the reports came from'),
	('COM-104', 'Features', 'Dashboard for health authorities showing trending misinformation', 'carried', 'afya.analytics.service:AnalyticsService.dashboard', "§19.4's `misinformation_velocity` dashboard is a topic-grouped velocity count; its data read is unwired, so the dashboard renders empty"),
	('COM-104', 'Features', 'Push notification with corrections when a rumour the user flagged is addressed', 'carried', 'afya.community.service:CommunityService.notify_flaggers', '`flagger_ref` is now read: `flaggers_for` resolves the people who reported the rumour and each is handed the correction the protocol drafted, through `ChannelService.push` — which existed with no call sites, so the drafted correction and the named flagger were never joined. Three refusals are reported rather than dropped: an undrafted topic is not answered with the fallback, an unsubscribed person is not pushed to but keeps the correction to read (§ALT-003\'s own `community_alerts`, read through `AlertingService.should_deliver`), and a deployment with no transport says so. Keyed on `(topic, subject_ref)` so a re-flag re-notifies nobody'),
	# --- §11.5 LOC-002: Bluetooth Proximity Logging ------------------------------------------
	('LOC-002', 'How it works', 'Each device periodically generates an **Ephemeral Bluetooth Identifier (EBID)** and broadcasts it over BLE.', 'carried', 'afya.location.service:LocationService.rotate_ebid', None),
	('LOC-002', 'How it works', 'Devices collect EBIDs of encountered devices and generate **Private Encounter Tokens (PET)** that identify an encounter without revealing user identity.', 'carried', 'afya.location.views:EncounterToken', None),
	('LOC-002', 'How it works', 'EBIDs rotate every 15 minutes to prevent tracking.', 'carried', 'afya.location.views:EBID_ROTATION_MINUTES', None),
	('LOC-002', 'How it works', 'If a user later tests positive and consents, their PET tokens are uploaded to a secure server.', 'carried', 'afya.location.service:LocationService.declare_exposure', None),
	('LOC-002', 'How it works', "Other users' apps check against these tokens and notify them of exposure.", 'carried', 'afya.location.service:LocationService.check_exposure', None),
	('LOC-002', 'How it works', 'Declarations are routed through a **trusted proxy** to prevent social graph inference.', 'carried', 'afya.location.views:ExposureDeclaration', None),
	('LOC-002', 'Privacy properties', 'No location data used for proximity detection', 'carried', 'afya.location.views:EncounterToken', None),
	('LOC-002', 'Privacy properties', 'No centralised record of who met whom', 'carried', 'afya.location.views:EncounterToken', None),
	('LOC-002', 'Privacy properties', 'Opt-in only; can be disabled at any time', 'carried', 'afya.privacy.views:ConsentCategory', None),
	('LOC-002', 'Privacy properties', 'Open-source client for independent verification', 'missing', None, 'nothing makes the client open source — the tree carries no LICENSE and no source offer; §SEC-006\'s "Open-source client code" row is the same absence, and a repository\'s licence is not something this tree can assert about itself'),
	# --- §11.5 LOC-003: GPS Location History for Contact Tracing -----------------------------
	('LOC-003', 'How it works', 'Location data stored locally on-device in encrypted form', 'deferred', None, "the encrypted store is the device's own; the tree carries the geohashed `LocationHistory` a report is built from, and the encryption is the client OS keystore's (§SEC-003), so there is no server call to check"),
	('LOC-003', 'How it works', '21-day rolling window (configurable to 28 days)', 'carried', 'afya.location.views:LOCATION_WINDOW_DAYS', None),
	('LOC-003', 'How it works', 'If the user tests positive and consents, the app generates a location history report showing places visited during the exposure window', 'carried', 'afya.location.service:LocationService.build_report', None),
	('LOC-003', 'How it works', 'Report shared with health authorities through a secure channel', 'carried', 'afya.location.views:LocationReport', None),
	('LOC-003', 'How it works', '**Geohashing** anonymises location data before sharing', 'carried', 'afya.location.service:_geohash_cell', None),
	# --- §11.5 LOC-004: QR Code and NFC Check-In ---------------------------------------------
	('LOC-004', 'Deployment points', 'Border posts and points of entry', 'carried', 'afya.location.views:CheckInPoint', None),
	('LOC-004', 'Deployment points', 'Health facilities and screening points', 'carried', 'afya.location.views:CheckInPoint', None),
	('LOC-004', 'Deployment points', 'Isolation and treatment units', 'carried', 'afya.location.views:CheckInPoint', None),
	('LOC-004', 'Deployment points', 'Vaccination points', 'carried', 'afya.location.views:CheckInPoint', None),
	('LOC-004', 'Deployment points', 'Schools and workplaces during an outbreak', 'carried', 'afya.location.views:CheckInPoint', None),
	('LOC-004', 'Deployment points', 'Events and gatherings', 'carried', 'afya.location.views:CheckInPoint', None),
	('LOC-004', 'Behaviour', 'Scan QR or tap NFC', 'deferred', None, "scanning a code or tapping a tag is the device's; the server records the `method` the client reports (`qr|nfc|manual`), and the coverage gate lists NFC reading as on-device (`SENS-010`)"),
	('LOC-004', 'Behaviour', 'App displays location-specific guidance', 'carried', 'afya.location.service:LocationService.GUIDANCE', None),
	('LOC-004', 'Behaviour', 'Check-in logged locally; synced with consent', 'carried', 'afya.location.service:LocationService.check_in', None),
	('LOC-004', 'Behaviour', 'Used for attendance tracking, follow-up scheduling, and exposure window determination', 'carried', 'afya.location.service:LocationService.follow_up', 'the three uses are three derivations off the stored check-ins: `attendance` joins each `CheckIn.point_token` to its `CheckInPoint` (a join nothing made — `check_in` builds a receipt from it and the receipt is not kept), `schedule` puts the asks on `EXPOSURE_FOLLOWUP_DAYS` from the check-in instant, and `window` does arithmetic on `CheckIn.at_iso` over §MON-009\'s 21 days. A point whose guidance names no watch (`WATCH_KINDS` = border post, event) opens no window, asserted at import against `GUIDANCE`; a subject with no check-ins is answered with `attendance: null` and a note rather than an empty list that reads like a clean record'),
	# --- §11.5 LOC-005: Border and Point-of-Entry Module -------------------------------------
	('LOC-005', 'Features', 'Pre-travel advisory by destination', 'carried', 'afya.location.service:LocationService.advisory', 'served by `/location/travel-advisory`'),
	('LOC-005', 'Features', 'Screening queue status at major border points', 'carried', 'afya.location.views:BorderPost', '`queue_minutes` and `screening_required`, read by `/location/border/{post_id}`'),
	('LOC-005', 'Features', 'Self-declaration form (digital, replaces paper)', 'carried', 'afya.location.views:TravelerDeclaration', 'posted to `/location/traveller/declare`'),
	('LOC-005', 'Features', '21-day post-arrival monitoring enrolment', 'carried', 'afya.location.views:TravellerEnrolment', "`self_declare` enrols for 21 days with a `[1, 3, 7, 14, 21]` schedule; it is a separate enrolment from MON-009's contact diary, not an enrolment into it"),
	('LOC-005', 'Features', 'Post-arrival symptom reporting', 'carried', 'afya.location.service:LocationService.report_arrival_day', 'a report on any scheduled day (1, 3, 7, 14, 21), answered with §MON-009\'s own escalation rule read off `MONITORING_ALERT_SYMPTOMS`; a day outside the schedule is refused rather than silently accepted'),
	('LOC-005', 'Features', 'Multi-language support for cross-border travellers', 'carried', 'afya.strings:traveller', 'the advisory, the enrolment acknowledgement, the daily prompt and both report outcomes are served through `traveller()`, in the language the traveller declared; a language with no table is served English on §ACC-002\'s `answerable` rule, and the traveller path offers only the languages it can answer in'),
	('LOC-005', 'Features', 'Integration with mobile laboratory results at border points', 'carried', 'afya.location.views:BorderPost', '`mobile_lab`, `lab_turnaround_hours` and `lab_tests` describe the post\'s on-site testing, validated to move together; the national result itself reaches a person through §REC-001\'s `LabResult` wallet document, which the border screen is the entry to rather than a second copy of'),
	# --- §11.7 AI-001: Community-Level Risk Prediction ---------------------------------------
	('AI-001', 'Inputs', 'Aggregated symptom reports', 'carried', 'afya.ai.views:AggregateCell', '`fever_reports` and `cough_events` are the counts `AIService.hotspots` reads, and `population` is the denominator `MIN_CELL_SIZE` tests before a cell is published.'),
	('AI-001', 'Inputs', 'geofence entries', 'carried', 'afya.ai.service:AIService.cells_from_signals', '`geofence_entries` is a distinct-subject count per cell, the same quantity `integrations.feeds.build_geofence_feed` aggregates — counted in subjects and not events, for the same reason that builder states. The count is the caller\'s because the min-cell floor lives in the module that owns the aggregation, and `AIService.cells_from_signals` is the bridge that carries it into the model.'),
	('AI-001', 'Inputs', 'proximity encounter density', 'carried', 'afya.ai.views:AggregateCell', '`encounter_density`, a float per cell, from the pseudonymous proximity tokens `analytics` counts.'),
	('AI-001', 'Inputs', 'crowdsourced facility reports', 'carried', 'afya.ai.views:AggregateCell', '`facility_reports`, an int per cell. Kept distinct from `search_signals`: §AI-001 names them as two Inputs, and reading the search ledger into this field would make two of the five one number wearing two names.'),
	('AI-001', 'Inputs', 'search and content-engagement signals', 'carried', 'afya.ai.service:AIService.cells_from_signals', '`search_signals` is fed from the `facility_search` and `medicine_search` rows of §AI-003\'s own `_signal_events` ledger — signals the product already recorded and never passed to the prediction.'),
	('AI-001', 'Outputs', 'Hotspot predictions', 'carried', 'afya.ai.service:AIService.hotspots', None),
	('AI-001', 'Outputs', 'transmission cluster identification', 'carried', 'afya.ai.service:AIService._cluster', '`TransmissionCluster` with its `ClusterLink` edges, built by single-linkage over cells that cleared both the min-cell floor and the baseline. Distinct from `MisinfoCluster`, which clusters rumours by topic.'),
	('AI-001', 'Outputs', 'resource deployment recommendations', 'carried', 'afya.ai.service:AIService._recommend', '`ResourceRecommendation` per county, derived from the clusters and hotspots rather than from the raw cells, and rendered onto §18.3\'s `resource_deployment` feed by `POST /ai/hotspots/deploy` — the producer `feeds.build_resource_feed` was missing. `quantity` is `None` where the section\'s arithmetic does not determine one, and `auto_actioned` is refused by `model_post_init` (§19.3\'s human in the loop).'),
	# --- §11.7 AI-002: Personal Risk Scoring -------------------------------------------------
	('AI-002', 'Inputs', 'Symptoms', 'carried', 'afya.ai.views:RiskInputs', '`RiskInputs.symptoms` is a list read by `AIService.personal_risk`.'),
	('AI-002', 'Inputs', 'travel history', 'carried', 'afya.ai.views:RiskInputs', '`RiskInputs.travel_affected_area` is the travel-history boolean.'),
	('AI-002', 'Inputs', 'proximity encounters', 'carried', 'afya.ai.views:RiskInputs', '`RiskInputs.proximity_encounters` is the count of proximity encounters.'),
	('AI-002', 'Inputs', 'geofence entries', 'carried', 'afya.ai.views:RiskInputs', '`RiskInputs.geofence_entry` is the geofence-entry boolean.'),
	('AI-002', 'Inputs', 'known exposures', 'carried', 'afya.ai.views:RiskInputs', '`RiskInputs.exposure_contact` is the known-exposure input; it is a boolean, so a known exposure is representable as present or absent and not as a list.'),
	('AI-002', 'Output', 'Low / Moderate / High with actionable guidance', 'carried', 'afya.ai.views:RiskScore', '`RiskScore.band` is low/moderate/high and `guidance` is the actionable string; `computed_on_device` records the privacy clause.'),
	# --- §11.7 AI-003: Outbreak Early Warning Signal -----------------------------------------
